/* Тексти статті «Один колір — одне значення, одна дія — одне місце». Лише українська: англійська
   буде окремим проходом (ключ en додати поруч з uk — i18n.js падає на uk).
   r('id') — виноска на джерело: номер береться з window.SOURCES (data/content.js),
   тому content.js підключено раніше за цей файл. */
(function () {
  const order = (window.SOURCES || []).map((s) => s.id);
  const r = (...ids) => ids.map((id) => {
    const n = order.indexOf(id) + 1;
    return `<sup class="fn"><a href="#src-${id}" aria-label="Джерело ${n}">${n}</a></sup>`;
  }).join('');

  window.COPY = { uk: {
    'ui.title': 'Один колір — одне значення, одна дія — одне місце: як ми розплутували інтерфейс планувальника',
    'ui.brand': 'Один колір, одне місце',
    'ui.human': 'рішення людини',
    'ui.client': 'згода клієнта',
    'ui.future': 'майбутнє',
    'ui.click-expand': 'Клік — розкрити',
    'ui.expand-all': 'Розгорнути все',
    'ui.collapse-all': 'Згорнути все',
    'ui.play': 'Запустити',
    'ui.stop': 'Зупинити',
    'ui.step': 'Крок',
    'ui.plus': 'Плюси',
    'ui.minus': 'Мінуси',
    'ui.variant': 'Варіант',
    'ui.foot': 'Огляд складено в жовтні 2026 · джерела переглянуто 2026-10-11 · відстані й контраст — власні розрахунки автора (ΔE у CIELAB, формула WCAG) · розміри цілей — за стилями, без вимірювання в браузері · розбір описує стан продукту на дату огляду',

    'nav.1': 'Симптом',
    'nav.2': 'Чотири роботи',
    'nav.3': 'Скільки кольорів',
    'nav.4': 'Не лише колір',
    'nav.5': 'Розбір',
    'nav.6': 'Простота',
    'nav.7': 'Кнопки',
    'nav.8': 'Панелі',
    'nav.9': 'Як в інших',
    'nav.10': 'Чекліст',

    'hero.kicker': 'Стаття · дизайн інтерфейсів',
    'hero.title': 'Один колір — одне значення, одна дія — одне місце: як ми розплутували інтерфейс планувальника',
    'hero.lead': 'Gantt — наш планувальник проєктів: діаграма Ганта, люди, бюджет, ризики. У ньому вісім вкладок і два оформлення — блакитне й спокійне. Одного дня ми помітили, що помаранчевий у спокійному оформленні означає одразу кнопку, вибраний рядок, віху найму й великий блок без жодної кнопки. А поруч на діаграмі — червоний критичний шлях. Ми зупинились і перерахували, <b>що в нас означає кожен колір</b>. Потім так само перерахували кнопки: <b>де стоїть кожна дія</b>, скільки їх на одній панелі й чи на тому самому місці вона на сусідній вкладці. Тут — принципи, на які ми спирались, і два розбори: що знайшли. Як виправили — буде окремо.',
    'hero.s1.b': '4 роботи кольору',
    'hero.s1.s': 'стан, дія, категорія, величина',
    'hero.s2.b': '9 конфліктів',
    'hero.s2.s': 'один колір — кілька значень',
    'hero.s3.b': '15 проти 117',
    'hero.s3.s': 'відстань між дією й критичним шляхом',
    'hero.s4.b': '3 відкриті питання',
    'hero.s4.s': 'з варіантами, без вердикту',
    'hero.s5.b': '27–29 контролів',
    'hero.s5.s': 'на одній панелі «Плану»',
    'hero.s6.b': '20 діалогів',
    'hero.s6.s': 'один порядок кнопок',

    /* ── 01 ── */
    's1.h': 'Симптом: колір означає надто багато',
    's1.p': 'Як це виглядає зсередини продукту, що росте',
    's1.lead': 'Жодного дня ніхто не вирішував, що один колір означатиме чотири речі. Це сталося саме. З\'являвся новий елемент, йому треба було виділитись, а найпомітніший колір уже був під рукою. Так <b>колір дії</b> став ще й кольором вибраного, кольором даних і кольором прикраси.',
    's1.c1.k': 'Дані',
    's1.c1.t': 'Кнопка й віха — одного кольору',
    's1.c1.b': 'У спокійному оформленні колір дії — помаранчевий. Ним же намальовано віхи найму на часовій шкалі. Віха — це дані: на неї не треба тиснути.',
    's1.c2.k': 'Сусід',
    's1.c2.t': 'Критичний шлях поруч',
    's1.c2.b': `Критичний шлях у нас червоний — як і в Microsoft Project${r('msproject')}. У спокійному оформленні червоний і помаранчевий стоять поруч на колірному колі. На тонких лініях діаграми їх легко сплутати.`,
    's1.c3.k': 'Прикраса',
    's1.c3.t': 'Правило є, а код відстав',
    's1.c3.b': 'У нашій дизайн-системі записано: помаранчевий — лише дія, не декор. Та найбільша помаранчева пляма в продукті — блок на сторінці «Про продукт», у якому немає жодної кнопки.',
    's1.note': `<b>Чому це проблема.</b> Apple у своїх настановах каже прямо: не вживати той самий колір для різних значень. І наводить приклад: якщо кольором бренду позначено інтерактивну кнопку, тим самим або схожим кольором не можна оформлювати неінтерактивний текст${r('apple')}. Людина вчиться, що помаранчеве можна натиснути, — і потім тисне на те, що не натискається.`,

    /* ── 02 ── */
    's2.h': 'Чотири роботи кольору',
    's2.p': 'Стан, дія, категорія, величина — і чому їх не можна змішувати',
    's2.lead': 'Колір в інтерфейсі виконує чотири різні роботи. Плутанина починається там, де один відтінок беруть одразу на дві. Сам поділ — наш висновок із джерел; нижче видно, на що він спирається.',
    'job.state.k': 'Мала закрита шкала',
    'job.state.t': 'Стан',
    'job.state.b': `Добре, увага, проблема — зміст сталий. У GitLab Pajamas зелений — успіх, помаранчевий — потрібна увага, червоний — проблема, синій — поточний або активний стан${r('pajamas')}. В IBM Carbon палітра ширша: червоний — небезпека чи помилка, помаранчевий — серйозне попередження, жовтий — звичайне, зелений — норма, синій — перебіг роботи, сірий — чернетки, фіолетовий — винятки${r('carbon-status')}.`,
    'job.act.k': 'Одна роль',
    'job.act.t': 'Дія',
    'job.act.b': `Колір, який каже «сюди можна натиснути». У Material 3 це «primary» — базовий колір для головних компонентів: помітних кнопок і активних станів${r('m3')}. В Atlassian головним діям відведено роль «бренд»${r('atlassian')}.`,
    'job.cat.k': 'Якісна палітра',
    'job.cat.t': 'Категорія',
    'job.cat.b': `Кольори лише відрізняють одне від одного й не натякають, що чогось більше чи менше${r('brewer')}. Atlassian називає такі кольори акцентними: за ними немає прив'язаного значення, і якщо один замінити іншим, нічого не має змінитись. Тому акцент не беруть там, де колір несе зміст${r('atlassian')}.`,
    'job.mag.k': 'Послідовна шкала',
    'job.mag.t': 'Величина',
    'job.mag.b': `Для впорядкованих даних від малого до великого${r('brewer')}. Stephen Few радить одну барву або кілька близьких: від блідого для малих значень до темнішого для великих${r('few')}.`,
    's2.why.h': 'На що це спирається',
    's2.why.lead': `Few називає три призначення кольору в даних: виділити окремі дані, згрупувати елементи, закодувати кількість. Звідси його правила: колір — лише коли він служить меті повідомлення; різні кольори — лише коли за ними різниця змісту; спокійні кольори для більшості даних, яскраві або темні — для того, що потребує уваги${r('few')}. Maureen Stone зводить добір до трьох правил: призначати колір за функцією; контраст — щоб виділити, подібність — щоб згрупувати; тримати контраст світлоти заради читабельності. Вона ж цитує Тафті: перший принцип кольору в інформації — «не зашкодь»${r('stone')}.`,
    's2.note': `<b>Коротко.</b> Стан — мала шкала зі сталим змістом. Дія — одна роль. Категорія — палітра без змісту, кольори в ній взаємозамінні. Величина — шкала однієї барви. «Одне значення на колір» — це правило Apple${r('apple')} і четверте правило Few${r('few')}, лише сказане коротше.`,

    /* ── 03 ── */
    's3.h': 'Скільки кольорів витримує екран',
    's3.p': 'Єдиного числа немає — є діапазон',
    's3.lead': 'Хочеться мати поріг: «не більше стількох-то кольорів». Джерела, які ми відкрили, такого порогу не дають. Вони дають діапазон, і він залежить від задачі.',
    'cnt.stone.n': '2–3',
    'cnt.stone.t': 'барви — Stone',
    'cnt.stone.b': `Найкращий результат зазвичай дає палітра з двох-трьох барв. Різницю всередині дають світлота й насиченість. Надмір барв створює візуальний шум${r('stone')}.`,
    'cnt.pajamas.n': '5',
    'cnt.pajamas.t': 'барв — GitLab Pajamas',
    'cnt.pajamas.b': `Типова якісна послідовність для графіків: синя, помаранчева, бірюзова, зелена, пурпурова. Синя завжди перша${r('pajamas-viz')}.`,
    'cnt.few.n': '8',
    'cnt.few.t': 'барв — Few',
    'cnt.few.b': `Зразок палітри для категорій у його правилах — вісім барв${r('few')}.`,
    'cnt.carbon.n': '14',
    'cnt.carbon.t': 'кольорів — IBM Carbon',
    'cnt.carbon.b': `Палітра для категорій на графіках. Брати кольори треба строго за порядком${r('carbon-viz')}.`,
    's3.shape.h': 'Чому форма не рятує строкатість',
    's3.shape.lead': `Спокуса зрозуміла: кольорів забагато — додамо значки й форми, і все розрізнятиметься. Christopher Healey в огляді «Perception in Visualization» пояснює, чому це не працює. Зорова система віддає перевагу кольору над формою: строкатість кольору заважає бачити форми, а строкатість форм бачити колір не заважає. А ціль, задану поєднанням двох неунікальних ознак око миттєво зазвичай не знаходить${r('healey')}.`,
    's3.shape.lead2': `Щоб набір кольорів був однаково розрізнюваний, за Healey треба контролювати три речі: відстань між кольорами, лінійну відокремлюваність і належність до названої кольорової категорії${r('healey')}. Відстань ми далі рахуємо для власних ролей.`,
    's3.note': `<b>Порядок дій.</b> Спершу скоротити кількість кольорів на екрані, потім додавати форму й підпис. І перевірка від Stone: спершу зробити правильно в чорно-білому — уся важлива інформація має читатись і без кольору${r('stone')}.`,

    /* ── 04 ── */
    's4.h': 'Колір не єдиний носій змісту',
    's4.p': 'Вимоги WCAG, контраст і червоний із зеленим',
    's4.lead': 'Навіть ідеально підібраний колір хтось не побачить: через особливості зору, поганий екран чи чорно-білий друк. Тому в стандарті доступності WCAG це окрема вимога, і вона стоїть на найпершому рівні — A.',
    'wcag.141.k': 'WCAG 1.4.1 · рівень A',
    'wcag.141.t': 'Не лише кольором',
    'wcag.141.b': `Колір не може бути єдиним візуальним засобом передати інформацію, позначити дію, спонукати до відповіді чи вирізнити елемент. Якщо кольори різняться ще й світлотою з контрастом 3:1 і більше, це зараховується як додаткова відмінність. Але якщо людина мусить розпізнати саме конкретний колір, додаткова позначка потрібна за будь-якого контрасту${r('wcag141')}.`,
    'wcag.143.k': 'WCAG 1.4.3 · рівень AA',
    'wcag.143.t': 'Текст: 4.5:1',
    'wcag.143.b': `Контраст тексту з тлом — щонайменше 4.5:1. Для великого тексту (від 18 пт або від 14 пт жирного) — 3:1. Для неактивних елементів, декору й логотипів вимоги немає. Число 4.5:1 виведено з потреб людей із гостротою зору 20/40${r('wcag143')}.`,
    'wcag.1411.k': 'WCAG 1.4.11 · рівень AA',
    'wcag.1411.t': 'Знаки й межі: 3:1',
    'wcag.1411.b': `3:1 до сусідніх кольорів — для ознак, за якими розпізнають елемент інтерфейсу та його стан, і для частин графіки, потрібних для розуміння. Індикатор фокуса сюди входить. Лінії графіка не мусять контрастувати одна з одною${r('wcag1411')}.`,
    's4.rg.h': 'Червоний із зеленим',
    's4.rg.lead': `Найчастіший тип порушення колірного зору — червоно-зелений${r('nei')}. Скільки людей він стосується, джерела кажуть по-різному. Ми не згладжуємо розбіжність, а показуємо всі три оцінки.`,
    'share.h.who': 'Джерело',
    'share.h.what': 'Оцінка',
    'share.okabe.who': 'Okabe й Ito',
    'share.okabe.what': `8% чоловіків європейського походження, 5% азійського, 4% африканського${r('okabe')}`,
    'share.nei.who': 'National Eye Institute (США)',
    'share.nei.what': `приблизно 1 з 12 чоловіків${r('nei')}`,
    'share.few.who': 'Few',
    'share.few.what': `приблизно 10% чоловіків і 1% жінок${r('few')}`,
    's4.rg.after': `Що з цим робити, джерела кажуть однаково. Few: не поєднувати червоний і зелений в одному показі; для «плюс/мінус» краще синій і червоний${r('few')}. Pajamas: червоний із зеленим разом проблемні; для пари «успіх/невдача» краще зелений із пурпуровим${r('pajamas-viz')}.`,
    's4.dup.h': 'Чим дублювати колір',
    'dup.okabe.t': 'Okabe й Ito: три правила',
    'dup.okabe.b': `Добирати схеми, які розрізняють люди з усіма типами колірного зору. Брати не лише різні кольори, а й різні форми, позиції, типи ліній, штрихування. Називати кольори там, де про них говоритимуть. І підписувати елементи просто на графіку, а не у винесеній кольоровій легенді${r('okabe')}.`,
    'dup.atlassian.t': 'Atlassian: вибране',
    'dup.atlassian.b': `Вибране має вирізнятися ще чимось, крім кольору: позначкою, підкресленням, рамкою, зміною форми${r('atlassian')}.`,
    'dup.pajamas.t': 'Pajamas: графіки',
    'dup.pajamas.b': `Стан на графіку — з текстом і додатковими позначками. Між сусідніми кольоровими елементами — проміжок щонайменше 1 px кольором поверхні або рамка${r('pajamas-viz')}.`,
    's4.note': `<b>Де джерела розходяться.</b> Okabe й Ito радять штрихування${r('okabe')}. Pajamas заливок-візерунків не підтримує: за їхніми словами, вони самі створюють проблеми доступності${r('pajamas-viz')}. Ми з цього беремо спільне: підпис, форма й товщина лінії — надійніші за візерунок.`,

    /* ── 05 ── */
    's5.h': 'Розбір планувальника: що ми знайшли',
    's5.p': 'Реєстр ролей, конфлікти, відстані. Без «як стало»',
    's5.lead': 'Ми пройшли стилі й код, що малює діаграму, і виписали: який токен що означає й де вжитий. <b>Токен</b> — це іменований колір: у коді пишуть не «помаранчевий», а «колір дії», а саме значення задає оформлення. Добра новина: система вже зріла. Ролі названо, стани мають окремі трійки кольорів (заливка, тло, текст), критичний шлях має власну роль, окрему від помилки. Проблема не в палітрі, а в кількох місцях, де роль ужито не за призначенням.',
    's5.map.lead': 'Схема читається зліва направо: <b>роль → токен → місця в інтерфейсі</b>. Смуги — чотири роботи кольору з розділу 2. Дві праві колонки — місця, які взяли чужий колір; кожне стоїть у смузі тієї роботи, яку воно виконує насправді. Пунктирний дріт — запозичення. Натисніть на картку, щоб побачити подробиці, або запустіть сценарій.',
    's5.map.note': '<b>Як читати.</b> Суцільний дріт не виходить зі своєї смуги: роль, токен і місце роблять одну роботу. Пунктирний завжди перетинає межу смуги. Сім таких дротів виходять з одного токена — кольору дії. Нижня смуга — місця, для яких ролі ще немає взагалі: вони взяли найближчий помітний колір.',

    's5.dist.h': 'Відстані між ролями',
    's5.dist.lead': 'Чи сперечаються два кольори, залежить від відстані між ними. Ми порахували її як ΔE у просторі CIELAB для значень світлої теми. Це власні розрахунки автора, а не дані з джерел. Орієнтир такий: менше 10 — майже однаково, 10–20 — близько, понад 40 — впевнено різні.',
    'dist.skin.sky': 'Блакитне',
    'dist.skin.calm': 'Спокійне',
    'dist.h.pair': 'Пара ролей',
    'dist.h.de': 'ΔE',
    'dist.crit-act': 'критичний шлях ↔ дія',
    'dist.crit-err': 'критичний шлях ↔ помилка',
    'dist.act-err': 'дія ↔ помилка',
    'dist.act-clay': 'дія ↔ людина «clay»',
    'dist.crit-clay': 'критичний шлях ↔ людина «clay»',
    'dist.bar-slate': 'типова смуга ↔ людина «slate»',
    'dist.warn-gold': 'увага ↔ людина «gold»',
    'dist.zone14': 'зона ризику 1 ↔ зона 4',
    'dist.v.same': 'майже однаково',
    'dist.v.near': 'близько',
    'dist.v.mid': 'розрізняються',
    'dist.v.far': 'впевнено різні',
    'dist.sum.sky': '<b>Блакитне.</b> Критичний шлях і дія стоять на протилежних боках колірного кола: відстань 117. Конфлікту немає. Найближча пара — критичний шлях і колір людини «clay» (24).',
    'dist.sum.calm': '<b>Спокійне.</b> Критичний шлях і дія — сусіди: відстань 15. У дузі 60° колірного кола тут зібралися чотири ролі — помилка, критичний шлях, дія й увага — і ще колір людини «clay». А типова смуга задачі майже збігається з кольором людини «slate» (7).',
    's5.dist.note': `<b>Про зелене й червоне.</b> Для звичайного зору зелена й червона зони ризику далекі одна від одної (115–116). Ми прогнали їх ще й через модель дейтеранопії — порушення зору, за якого червоне й зелене розрізняються погано. За моделлю зони майже зливаються в обох оформленнях. Цей результат ще потребує перевірки в симуляторі, тому чисел не наводимо. Висновок від них не залежить: розрізняти зони має підпис, число чи форма, а не лише колір${r('wcag141')}.`,

    's5.conf.h': 'Дев\'ять конфліктів: один колір — кілька значень',
    'conf.h.what': 'Що знайшли',
    'conf.h.why': 'Чому це конфлікт',
    'conf.k1.what': 'Колір дії малює дані: віхи найму на часовій шкалі.',
    'conf.k1.why': 'У спокійному оформленні це помаранчеві ромби поруч із червоними критичними лініями. Для даних у нас є окремий токен — його тут просто не взяли.',
    'conf.k2.what': 'Колір дії малює вибране й наведене на полотні: рамку активної смуги, наведену стрілку, підсвітку задач ризику.',
    'conf.k2.why': 'За кодом, наведена стрілка стає помаранчевою замість критично-червоної: два сусідні відтінки на лінії 1.75 px.',
    'conf.k3.what': 'Колір дії — тло змістового блоку на сторінці «Про продукт». У блоці немає жодної дії.',
    'conf.k3.why': 'Це найбільша пляма кольору дії в продукті. І вона суперечить нашому ж правилу: «помаранчевий — лише дія, не декор».',
    'conf.k4.what': 'Колір дії показує перебіг і стан: смужку перегляду трейлера, номер кроку, крапку показу «як заповнити», крапку «є незбережені зміни», рамку плитки «для клієнта».',
    'conf.k4.why': 'Перебіг — це дані. «Не збережено» — стан. Жодне з них не дія.',
    'conf.k5.what': 'Стан «триває» показано кольором дії: позначка «активний» у шапці, «в роботі» в асистенті.',
    'conf.k5.why': `У блакитному синій «триває» збігається зі звичаєм систем дизайну${r('pajamas', 'carbon-status')}. У спокійному «триває» стає помаранчевим — кольором дії й сусідом «уваги».`,
    'conf.k6.what': 'Кольори людей вжито для трьох речей: людина, колір задачі на вибір користувача, групи в аудиті команди.',
    'conf.k6.why': 'Наше правило — «кольори людей — ідентичність, ніколи не стан». В аудиті воно порушене. А смуга кольору «slate» у спокійному майже не відрізняється від типової.',
    'conf.k7.what': 'Шкала зон ризику 1–4 передає ще й стан людини та теплокарту аудиту.',
    'conf.k7.why': 'Зміст близький — «від доброго до поганого», тож це терпимо. Але зона 4 й «помилка» — той самий колір.',
    'conf.k8.what': 'Колір «уваги» означає демо-режим в асистенті.',
    'conf.k8.why': `Демо — не попередження. В Atlassian для нового є окрема роль — «відкриття»${r('atlassian')}.`,
    'conf.k9.what': 'Слово «crit» у назвах стилів означає і критичний шлях, і критичну проблему якості.',
    'conf.k9.why': 'Плутанина в коді, не на екрані. Але це ризик узяти не той токен під час правки.',
    's5.conf.after': 'Буває й навпаки: одне значення — два кольори. «Жовтий» стан людини в застосунку жовтий, а в асистенті бурштиновий. Лінія «сьогодні» в блакитному оформленні має колір дії, у спокійному — окремий приглушений синій.',

    's5.sole.h': 'Де колір — єдиний носій змісту',
    's5.sole.lead': `Окремо ми виписали місця, які треба перевірити за критерієм WCAG 1.4.1${r('wcag141')}: що лишиться, якщо колір прибрати.`,
    'sole.h.place': 'Місце',
    'sole.h.else': 'Що є, крім кольору',
    'sole.ok': 'продубльовано',
    'sole.bad': 'лише колір',
    'sole.stake.t': 'Ставлення стейкхолдера: прихильник чи опонент',
    'sole.stake.b': 'Лише колір рамки. Число всередині — інший показник. Легенда є.',
    'sole.rbs.t': 'Крапка зони ризику в дереві ризиків',
    'sole.rbs.b': 'Нічого.',
    'sole.sprint.t': 'Лінія картки спринту: «переливається» чи «перевантажено»',
    'sole.sprint.b': 'На самій картці — нічого.',
    'sole.idle.t': 'Простій людини проти завантаження',
    'sole.idle.b': 'Висота стовпчика.',
    'sole.late.t': 'Прострочена смуга на діаграмі',
    'sole.late.b': 'На діаграмі — лише червона рамка. У таблиці є мітка й дата.',
    'sole.crit.t': 'Критичний шлях',
    'sole.crit.b': 'Товща лінія, скоба над етапом, контур віхи, значок у таблиці, квадратна крапка в позначці.',
    'sole.risk.t': 'Ризик на смузі задачі',
    'sole.risk.b': 'Форма значка різна для загрози, можливості й захисту.',
    's5.contrast': `<b>Контраст.</b> Ми рахували його за формулою WCAG до білого тла; перше число — блакитне оформлення, друге — спокійне. Більшість ролей у межах вимог${r('wcag143', 'wcag1411')}: критичний шлях 3.63 і 5.64, дія 4.61 і 4.66, помилка 4.96 і 5.06, «добре» 3.44 і 3.44. Нижче 3:1 — «увага» (2.31 і 2.19) та жовта зона ризику (1.72 і 1.63). Як тло вони безпечні. Як самостійний знак на білому — крапка, значок, тонка лінія — слабкі. Це теж наші розрахунки.`,

    's5.q.h': 'Три відкриті питання',
    's5.q.lead': 'Розбір закінчився трьома питаннями, на які в нас ще немає відповіді. Показуємо варіанти з плюсами й мінусами — без вердикту.',
    'q.q1.name': 'Критичний шлях і дія',
    'q.q1.t': 'Червоний критичний шлях проти помаранчевої дії',
    'q.q1.b': `Конфлікт є лише в спокійному оформленні: відстань 15 проти 117 у блакитному. На полотні обидва кольори малюють тонкі лінії й контури. Критичний шлях уже продубльовано формою, а червоний для нього звичний: так само в Microsoft Project${r('msproject')}.`,
    'q.q1.a.t': 'Лишити кольори, прибрати колір дії з полотна: вибране й наведене — темним контуром або окремим токеном вибору, віхи найму — токеном даних.',
    'q.q1.a.plus': 'Найменша правка. Червоний критичний шлях відповідає звичці. На діаграмі лишається один теплий колір зі змістом.',
    'q.q1.a.minus': 'Вибране в таблиці й на полотні виглядатиме по-різному. Новий токен у чотирьох наборах кольорів.',
    'q.q1.b.t': 'Відсунути критичний шлях від дії: у спокійному зробити його темним і товстим або пурпурово-червоним.',
    'q.q1.b.plus': `Теплу дугу розвантажено. Критичний шлях читається й у чорно-білому друку${r('stone')}.`,
    'q.q1.b.minus': `Ламає звичку «критичне — червоне»${r('msproject')}. Пурпуровий упирається в помилку. Два оформлення почнуть різнитись змістом, а не лише виглядом.`,
    'q.q1.c.t': 'Змінити колір дії в спокійному оформленні: не помаранчевий.',
    'q.q1.c.plus': 'Конфлікт зникає повністю.',
    'q.q1.c.minus': 'Втрачається суть оформлення: воно побудоване довкола помаранчевого сигналу.',
    'q.q1.d.t': 'Нічого не міняти, покластись на форму.',
    'q.q1.d.plus': 'Нуль роботи.',
    'q.q1.d.minus': `Колір сильніший за форму${r('healey')}: близькі відтінки на тонких лініях плутатимуться далі.`,
    'q.q2.name': 'Блок на «Про продукт»',
    'q.q2.t': 'Помаранчевий блок без жодної кнопки',
    'q.q2.b': `Змістовий блок на сторінці «Про продукт» залито кольором дії. Усередині немає ні кнопки, ні посилання. У блакитному це синя плашка бренду. У спокійному той самий токен дає велику помаранчеву площу — проти правила самого оформлення. За Apple, колір, яким позначено інтерактивне, не беруть для неінтерактивного${r('apple')}.`,
    'q.q2.a.t': 'Темна плашка в обох оформленнях.',
    'q.q2.a.plus': 'Наголос зберігається, колір дії вільний, жодного нового токена.',
    'q.q2.a.minus': 'У блакитному сторінка втрачає синю пляму бренду.',
    'q.q2.b.t': 'Новий токен «тло наголошеного блоку»: у блакитному він дорівнює кольору дії, у спокійному — темному.',
    'q.q2.b.plus': 'У блакитному нічого не змінюється. У спокійному правило дотримано.',
    'q.q2.b.minus': 'Ще одна роль у чотирьох наборах кольорів.',
    'q.q2.c.t': 'Біла картка з тонкою помаранчевою смужкою зверху.',
    'q.q2.c.plus': 'Найспокійніше: помаранчевого лишається 2 px.',
    'q.q2.c.minus': 'Блок перестає вирізнятись серед сусідніх карток.',
    'q.q2.d.t': 'Лишити й записати виняток: на промо-сторінках колір бренду можна як тло.',
    'q.q2.d.plus': 'Нуль роботи.',
    'q.q2.d.minus': 'Правило «помаранчевий — лише дія» перестає бути правилом.',
    'q.q3.name': 'Документи',
    'q.q3.t': 'Чи потрібне окреме оформлення для документів',
    'q.q3.b': 'Пропозиція, звіт, картинка діаграми й друк завжди беруть світлу тему. Але оформлення вони успадковують від того, хто експортує. Той самий документ виходить блакитним або сіро-помаранчевим — залежно від налаштувань автора. І колір дії в документі вжито двічі, обидва рази не для дії: точка на графіку й плашка «внутрішня версія».',
    'q.q3.a.t': 'Окремий «документний» набір ролей, незалежний від оформлення: нейтральний текст і лінії, один колір даних, трійка станів. Кольору дії немає зовсім.',
    'q.q3.a.plus': `Документ однаковий у всіх. У документі немає дій — отже й кольору дії${r('apple')}. Добре друкується й читається в чорно-білому${r('stone')}.`,
    'q.q3.a.minus': 'Третій набір токенів, який треба тримати під тестом контрасту. І треба вирішити, чий це «бренд».',
    'q.q3.b.t': 'Не набір, а правило: документ завжди з одного наявного оформлення; колір дії в ньому замінити на колір даних і «увагу».',
    'q.q3.b.plus': 'Майже без нового коду. Документ стає відтворюваним.',
    'q.q3.b.minus': 'Документ назавжди прив\'язано до вигляду одного оформлення.',
    'q.q3.c.t': 'Вибір оформлення в діалозі експорту.',
    'q.q3.c.plus': 'Гнучко.',
    'q.q3.c.minus': `Ще один перемикач: кожна зайва одиниця змагається з потрібними${r('heuristics')}. Проблема «колір дії в документі» лишається.`,
    'q.q3.d.t': 'Колір із брендування замовника.',
    'q.q3.d.plus': 'Сильно для пропозиції.',
    'q.q3.d.minus': `Довільний колір може не пройти контраст${r('wcag143')}. Найбільша робота.`,
    'q.q3.e.t': 'Лишити як є.',
    'q.q3.e.plus': 'Нуль роботи.',
    'q.q3.e.minus': 'Той самий документ і далі виходитиме різним.',
    's5.note': '<b>Чому без «як стало».</b> Це розбір, а не звіт про перемогу. Рішень у трьох питаннях ще немає. Що ми вибрали й що з цього вийшло — напишемо окремо, коли буде що показати.',

    /* ── 06 ── */
    's6.h': 'Складне, але просте',
    's6.p': 'Складність росте не екранами, а режимами',
    's6.lead': 'Колір — лише половина історії. Друга половина — скільки всього людина бачить одразу. Ми порахували й це. Складність у нас росте не кількістю екранів, а <b>режимами, що перемножуються</b>, і шапкою, де зібрано близько 26 елементів. Тут — загальні принципи простоти й два приклади; де стоять кнопки й скільки їх, докладно розібрано в розділах <a href="#buttons">7</a> і <a href="#layout">8</a>.',
    'pr.disclose.t': 'Поступове розкриття',
    'pr.disclose.b': `Просунуті й рідкісні функції відкладають на другий екран. Це покращує вивчуваність і швидкість, зменшує помилки. Умов дві: правильно поділити функції на перші й другі та зробити перехід між ними очевидним. Понад два рівні розкриття зазвичай дають низьку зручність${r('nielsen-pd')}.`,
    'pr.overview.t': 'Спершу огляд',
    'pr.overview.b': `Формула Ben Shneiderman: спершу огляд, потім масштаб і фільтр, далі подробиці на вимогу${r('shneiderman')}.`,
    'pr.clutter.t': 'Менше захаращеності, не менше можливостей',
    'pr.clutter.b': `Настанови NN/g для складних застосунків: зменшувати захаращеність, не зменшуючи можливостей; робити важливе візуально помітним; не виводити людину з головного екрана заради додаткової інформації${r('kaplan')}. Восьма евристика Нільсена пояснює чому: кожна зайва одиниця інформації змагається з потрібною${r('heuristics')}.`,
    'pr.modes.t': 'Режими — на видноті',
    'pr.modes.b': `Режим — це коли той самий ввід дає різний результат залежно від активного стану. Помилка режиму стається, коли людина не знає, який режим активний. Порада: показувати активний режим щонайменше двома візуальними ознаками й називати режими словами${r('modes')}.`,
    'pr.primary.t': 'Одна головна дія',
    'pr.primary.b': `IBM Carbon: одна головна кнопка на сторінку; виняток — тимчасові потоки зі своєю головною дією. Понад три дії — збирати в меню${r('carbon-button')}.`,
    'pr.empty.t': 'Порожній стан працює',
    'pr.empty.b': `Порожній стан має повідомити стан системи, навчити в контексті й дати прямий шлях до дії, яка наповнить екран. Зовсім порожній екран викликає сумнів, чи система працює${r('empty')}.`,
    's6.ex.h': 'Два приклади з планувальника',
    'ex.header.k': 'Приклад 1',
    'ex.header.t': 'Шапка',
    'ex.header.n': '≈ 26',
    'ex.header.ns': 'елементів у шапці',
    'ex.header.b': `У шапці близько двадцяти інтерактивних елементів і шість текстових: назва, версія, етап, дати, вартість, стан, обмеження, вісім вкладок, «Зберегти», команди. Другий рядок під назвою несе до шести різнорідних позначок. Кожна з них змагається з рештою${r('heuristics')}. Повний склад шапки й три варіанти, як його змінити, — у <a href="#layout">розділі 8</a>.`,
    'ex.toolbar.k': 'Приклад 2',
    'ex.toolbar.t': 'Панель «Плану»',
    'ex.toolbar.n': '27–29',
    'ex.toolbar.ns': 'контролів в одному ряду',
    'ex.toolbar.b': `Три перемикачі стоять поспіль: масштаб, вигляд, рядки. Те, що не влазить, ховається в меню «Ще» — і це добре. Але поділ на «перше» й «друге» визначає ширина екрана, а не частота вжитку${r('nielsen-pd')}. Режими перемножуються: вигляд × рядки × сценарій × дві панелі. Частину комбінацій програма вимикає, але людина цього наперед не бачить. І кожен режим позначено однією ознакою — підсвіченою клавішею перемикача, хоча варто двома${r('modes')}. Усю панель по групах розкладено на схемі в <a href="#layout">розділі 8</a>.`,
    's6.note': `<b>Що тут гаразд.</b> Головних кнопок на «Плані» дві: «Зберегти» в шапці й «Додати задачу». За Carbon шапка не рахується, тож формально порядок${r('carbon-button')}. Порожні стани є на більшості екранів — із заголовком, поясненням і головною кнопкою${r('empty')}. Їхню якість ми ще не перевіряли — лише наявність.`,

    /* ── 07 ── */
    's7.h': `Кнопки: де, скільки і в якому порядку`,
    's7.p': `Принципи розташування — і де джерела розходяться`,
    's7.lead': `Друга половина плутанини — не колір, а місце. Де стоїть головна кнопка, скільки дій на панелі, що сховати в меню. Ми зібрали настанови платформ і систем дизайну та дослідження, на які вони спираються. Одразу застереження: настанови Windows про діалоги, панелі й підтвердження написано за доби Windows 7, і Microsoft сама позначає їх як не оновлені. Беремо їх як класику — поруч із сучасними настановами для застосунків Windows.`,

    's7.ok.h': `Головна кнопка й порядок «підтвердити / скасувати»`,
    's7.ok.lead': `Jakob Nielsen розібрав це питання ще 2008 року: універсального порядку немає. В обох варіантів є доводи. «ОК першим» — природний порядок читання. «ОК останнім» — діалог закінчується висновком, як кнопка «Далі». Часто неважливо, що саме обрати; важливіше триматись звичаю платформи, ніж оптимізувати окремий діалог${r('okcancel')}. Настанови це підтверджують: вони розходяться.`,
    'ok.h.who': `Джерело`,
    'ok.h.where': `Де головна кнопка`,
    'ok.h.order': `Порядок у парі`,
    'ok.win.who': `Windows${r('win-dialog', 'win-cmdbar')}`,
    'ok.win.where': `праворуч унизу`,
    'ok.win.order': `ствердна → «Скасувати»`,
    'ok.apple.who': `Apple, сповіщення${r('apple-alerts')}`,
    'ok.apple.where': `праворуч`,
    'ok.apple.order': `«Скасувати» → типова`,
    'ok.carbon-d.who': `IBM Carbon, діалог${r('carbon-modal')}`,
    'ok.carbon-d.where': `праворуч`,
    'ok.carbon-d.order': `другорядна → головна`,
    'ok.carbon-p.who': `IBM Carbon, сторінка з формою${r('carbon-button')}`,
    'ok.carbon-p.where': `ліворуч`,
    'ok.carbon-p.order': `головна першою`,
    'ok.atl.who': `Atlassian, діалог${r('atl-modal')}`,
    'ok.atl.where': `праворуч`,
    'ok.atl.order': `другорядна → головна`,
    'ok.govuk.who': `GOV.UK, форма${r('govuk-button')}`,
    'ok.govuk.where': `ліворуч`,
    'ok.govuk.order': `головна першою`,
    'ok.nng.who': `Nielsen${r('okcancel')}`,
    'ok.nng.where': `—`,
    'ok.nng.order': `неважливо: тримайтесь платформи й будьте послідовні`,
    's7.ok.after': `Одна й та сама система — Carbon — дає два порядки залежно від місця: у діалозі головна кнопка праворуч, на сторінці з формою — ліворуч. Деталі теж різняться. Apple дозволяє до трьох кнопок у сповіщенні й радить назву з одного-двох слів про результат; «ОК» — лише в суто інформаційних сповіщеннях${r('apple-alerts')}. Atlassian радить, щоб головна дія повторювала заголовок діалогу${r('atl-modal')}. GOV.UK застерігає від кількох головних кнопок на сторінці: це зменшує їхню вагу${r('govuk-button')}.`,
    's7.ok.note': `<b>Тримайтесь однієї конвенції.</b> «Правильного» порядку немає. Є дві речі, з якими згодні всі: один порядок на весь продукт і дієслово замість «ОК». Найуживанішу кнопку роблять типовою й виділяють — крім випадку, коли дія небезпечна: тоді людина має обрати її явно, а не влучити клавішею Enter${r('okcancel')}.`,

    's7.bar.h': `Скільки дій на панелі і як їх групувати`,
    's7.bar.lead': `Класична настанова Windows каже: панель інструментів — не каталог, а швидкий доступ до часто вживаних, негайних і прямих команд. Вичерпний каталог — це меню. Якщо на панелі здебільшого кнопки-меню, це вже меню, а не панель${r('win-toolbars')}. Скільки саме дій лишати — джерела кажуть по-різному.`,
    'bar.apple.n': `3`,
    'bar.apple.t': `групи — Apple`,
    'bar.apple.b': `Елементи панелі добирають свідомо й групують за функцією та частотою. Загалом — не більше трьох груп. Місць три: початковий край — для навігації й заголовка, центр — для звичних дій, кінцевий край — для того, що має бути завжди: пошуку, меню «Ще», однієї головної дії${r('apple-toolbars')}.`,
    'bar.carbon.n': `5`,
    'bar.carbon.t': `дій — IBM Carbon`,
    'bar.carbon.b': `На панелі таблиці — до п'яти дій; решта йде в меню переповнення${r('carbon-table')}. Група кнопок — до трьох; більше — у кнопку-меню${r('carbon-button')}.`,
    'bar.winui.n': `4`,
    'bar.winui.t': `команди — Windows, екран 320 px`,
    'bar.winui.b': `Команди додають у порядку важливості, щоб найважливіші лишались видимими, коли вікно звужується. На найвужчому екрані влазить щонайбільше чотири${r('win-cmdbar')}.`,
    'bar.split.n': `10–12`,
    'bar.split.t': `пунктів — меню розділеної кнопки`,
    'bar.split.b': `Розділена кнопка доречна, коли один варіант уживають найчастіше. Стрілку чітко відділяють: саме мала стрілка — головне обмеження зручності. У меню — до 10–12 пунктів, без підменю${r('split')}.`,
    's7.bar.after': `Порядок на панелі теж описано. Команди збирають у споріднені групи; найуживаніші групи — першими; роздільники — лише між слабко пов'язаними групами. Знак переповнення — лише коли справді не влазить, і в малому вікні найуживаніші команди мають лишатись на панелі. Кнопки, що не стосуються поточного стану, вимикають, а не прибирають: так уміст панелі стабільний і його легше знайти${r('win-toolbars')}.`,
    's7.bar.after2': `Про меню «три крапки» NN/g каже жорсткіше. Воно лише для другорядних дій; часті й суттєві не ховають; одну-дві дії не ховають узагалі. Сам знак мало підказує про вміст, тому потрібен підпис або підказка. І в одному меню не змішують загальні дії з діями над конкретним елементом${r('ctxmenu')}. Клавіші, жести й інші швидкі шляхи — це додаткові способи: хто їх не вивчив, має зробити те саме звичайним шляхом${r('accel')}.`,
    's7.bar.note': `<b>Ділить частота, а не ширина.</b> Джерела сходяться в одному: на панелі лишається часте й пряме, решта йде в меню. Числа різні — три групи, п'ять дій, чотири команди на вузькому екрані. Це орієнтири, а не норми.`,

    's7.size.h': `Розмір цілі`,
    's7.size.lead': `Закон Фіттса: час руху до цілі росте з відстанню й падає з шириною цілі${r('mackenzie')}. Наслідки прості. Цілі роблять великими. Кнопка з іконки й підпису — більша ціль, ніж сама іконка. Краї екрана для миші — майже нескінченні цілі; для дотику — ні. Надто близькі малі цілі — ризик промаху. А пов'язані дії ставлять поруч: «Надіслати» — біля останнього поля${r('fitts')}.`,
    'size.w258.k': `WCAG 2.5.8 · рівень AA`,
    'size.w258.n': `24 px`,
    'size.w258.t': `Мінімум для вказівника`,
    'size.w258.b': `Ціль — щонайменше 24×24 CSS px. Менша проходить за винятком «відстань»: якщо коло діаметром 24 px із центром у її центрі не перетинає іншу ціль чи таке саме коло сусідньої малої цілі. Приклад зі стандарту: кнопки 20×20 із проміжком 4 px проходять, без проміжку — ні${r('wcag258')}.`,
    'size.w255.k': `WCAG 2.5.5 · рівень AAA`,
    'size.w255.n': `44 px`,
    'size.w255.t': `Розширена вимога`,
    'size.w255.b': `Ціль — 44×44 CSS px, з подібними винятками${r('wcag255')}. Це найвищий рівень відповідності, і щільні робочі інструменти його зазвичай не беруть за мету.`,
    'size.plat.k': `Платформи`,
    'size.plat.n': `28 · 44 · 48`,
    'size.plat.t': `Миша й дотик — різні числа`,
    'size.plat.b': `Apple: ділянка натискання кнопки — щонайменше 44×44 пт; на macOS типовий контрол — 28×28, мінімальний — 20×20${r('apple-buttons', 'apple-a11y')}. Android: для дотику — щонайменше 48×48 dp${r('android')}. Windows: ціль для дотику — близько 7,5 мм, тобто 40×40 px; між кнопками 8 px; цілі з тяжкими наслідками помилки — з більшим відступом${r('win-target', 'win-spacing')}.`,
    's7.size.note': `<b>Два режими.</b> Для миші в щільному робочому інтерфейсі опорні числа — 24 px як підлога і 28 px як звичайний розмір. Для дотику — 44–48. Це наш висновок із чисел вище. Щільні таблиці вкладаються в ті самі рамки: Carbon дає висоти рядка від 24 до 64 px${r('carbon-table')}, а WCAG прямо називає перемикач щільності способом виконати вимогу${r('wcag258')}.`,

    's7.n.h': `Скільки варіантів: Гік—Гайман і «сім» Міллера`,
    's7.n.lead': `Дві найчастіші цитати в розмовах про «забагато кнопок» — закон Гіка—Гаймана й «магічне число сім». Обидві зазвичай цитують неточно.`,
    'n.hick.t': `Гік—Гайман: логарифм, а не заборона`,
    'n.hick.b': `Час реакції вибору росте з логарифмом кількості рівноймовірних варіантів${r('mackenzie', 'hick-wiki')}. Автори огляду 2020 року пишуть, що в дизайні інтерфейсів цей закон часто розуміють хибно. Він говорить проти принципу «менше — краще», а не на його користь. Схема «стимул — відповідь» рідко стосується задач в інтерфейсі. Кориснішим є розбір зорового пошуку й ухвалення рішення${r('liu')}.`,
    'n.miller.t': `Міллер: не про меню`,
    'n.miller.b': `«Сім» у статті 1956 року — це межа абсолютного судження за однією ознакою й обсяг безпосередньої пам'яті. Про меню чи кількість варіантів в інтерфейсі там немає нічого. Наприкінці сам Міллер називає збіг сімок, імовірно, «згубним піфагорійським збігом»${r('miller')}. Пізніша оцінка N. Cowan: справжня межа — в середньому близько чотирьох «шматків»${r('cowan')}.`,
    'n.myth.t': `Міф про сім пунктів меню`,
    'n.myth.b': `Nielsen називає «не більше семи пунктів меню» поширеною хибною думкою. Меню спирається на впізнавання, а не на пригадування, тож довші меню допустимі. А надто короткі стають абстрактними й незрозумілими${r('stm')}. Alan Dix пояснює так само: у меню людина сканує видимі пункти, а не тримає їх у пам'яті. Обтяжлива не ширина, а глибина${r('dix')}.`,
    'n.depth.t': `Що обмежує насправді`,
    'n.depth.b': `Практичну межу ставить захаращеність екрана, а підписані розділи в межах одного рівня дають змогу сплощити глибоку структуру${r('dix')}. NN/g: понад два яруси меню — вкрай небажано; найуживаніше — ближче до місця, де меню відкривається${r('menus')}. Apple: важливе й часте — першим; підменю — один рівень${r('apple-menus')}.`,
    's7.n.note': `<b>Не різати до семи.</b> «Сім» не обмежує ні панель, ні меню. Наш висновок із джерел: обмежують їх зоровий пошук, глибина й захаращеність. Тому відповідь на «забагато» — групувати з підписами й прибирати рівні.`,

    's7.dng.h': `Небезпечні дії: підтвердження проти «повернути»`,
    's7.dng.lead': `Перша думка — спитати «Ви впевнені?». Джерела радять починати не з цього.`,
    'dng.rare.t': `Питати рідко й конкретно`,
    'dng.rare.b': `Nielsen: підтвердження — перед діями з тяжкими наслідками й тими, які не скасувати. Не для буденних: якщо попереджати надто часто, люди перестають зважати. У діалозі — конкретний наслідок і кнопки, що називають результат: «Видалити файл» і «Лишити файл», а не «Ви впевнені?». І докладати великих зусиль, щоб дати скасування${r('confirm')}.`,
    'dng.apart.t': `Відділити й дати «повернути»`,
    'dng.apart.b': `Класична настанова Windows: потреба в підтвердженні часто свідчить про ваду дизайну. Замінники — фізично відділити руйнівні команди від інших, дати скасування, дати зворотний зв'язок. Саме скасування не допоможе, якщо людина не помітила помилки${r('win-confirm')}. На панелі руйнівні команди не ставлять поруч із частими — або не тримають їх там узагалі, лише в меню${r('win-toolbars')}.`,
    'dng.default.t': `Не робити типовою`,
    'dng.default.b': `Apple: головну роль не дають кнопці з руйнівною дією, навіть якщо вона найімовірніша, — помітну кнопку інколи тиснуть, не читаючи. До руйнівної дії завжди додають «Скасувати»${r('apple-buttons', 'apple-alerts')}. Carbon: для руйнівних дій — окремий «небезпечний» діалог; небезпечну кнопку не роблять лише іконкою, потрібен підпис${r('carbon-modal', 'carbon-button')}.`,
    's7.dng.after': `WCAG закріплює це вимогою 3.3.4 рівня AA. Там, де змінюють чи видаляють дані користувача, має бути щонайменше одне з трьох: дію можна скасувати; дані перевіряються з можливістю виправити; є крок перегляду й підтвердження${r('wcag334')}. Суміжна пастка — хрестик. Він означає і «скасувати», і «закрити», і без підпису людина не знає, чи втратить роботу${r('cancel-close')}.`,
    's7.dng.note': `<b>Де джерела розходяться.</b> Apple радить не фарбувати червоним дію, яку людина обрала сама; їхній приклад — «Очистити кошик»${r('apple-buttons')}. Carbon і GOV.UK фарбують будь-яку руйнівну; GOV.UK додає: не покладатись лише на червоний колір${r('carbon-modal', 'govuk-button')}. Спільне в усіх: руйнівна дія не типова, відділена й названа словом.`,

    's7.ico.h': `Іконка чи підпис`,
    's7.ico.lead': `Іконок, які впізнають майже всі, одиниці: дім, друк, пошук. Решті потрібен текстовий підпис — видимий завжди, а не за наведенням${r('icons')}. Настанови платформ до панелей поблажливіші. Windows: звичайна кнопка панелі — іконка з підказкою, але найуживаніші команди з неочевидними іконками підписують; підписана кнопка займає щонайменше втричі більше місця${r('win-toolbars')}. Apple: на панелі — прості впізнавані символи замість тексту, крім дій, які символом не передати${r('apple-toolbars')}. Carbon: кнопки-іконки вживати ощадно, і підказка для них обов'язкова${r('carbon-button')}.`,
    's7.ico.lead2': `Якщо вже підказка, то повноцінна. Суттєвого в неї не кладуть, а показують її і за наведенням, і за фокусом із клавіатури — для всіх схожих елементів однаково${r('tooltips')}. Ще дві вимоги WCAG стосуються назв. 2.5.3, рівень A: якщо елемент має видимий підпис, його доступне ім'я — те, що чує екранний читач і розпізнає голосове керування, — має містити цей текст${r('wcag253')}. 3.2.4, рівень AA: елементи з однаковою функцією позначають однаково — одна іконка збереження скрізь${r('wcag324')}.`,

    's7.place.h': `Те саме місце на кожному екрані`,
    's7.place.lead': `Елементи поруч сприймаються як група, і головний інструмент тут — проміжок. Непов'язані кнопки поруч «маскують» одна одну, а далеко відставлене легко проґавити${r('proximity')}. Рамка чи спільне тло — сильніша ознака групи, ніж близькість. Її беруть, коли проміжком не обійтись: рамки заради прикраси додають шуму${r('region')}.`,
    's7.place.lead2': `Про сталість місць є вимога WCAG 3.2.3 рівня AA: навігація, що повторюється на сторінках одного набору, іде в тому самому порядку${r('wcag323')}. Формально вона про набір вебсторінок; для вкладок застосунку це аналогія, а не вимога. Настанови платформ кажуть те саме простіше. Windows: команду, що повторюється на різних сторінках, тримати в тому самому місці${r('win-cmdbar')}. Apple: пошук і головна дія — на кінцевому краю панелі, навігація — на початковому${r('apple-toolbars')}. NN/g: люди шукають певні меню в певних місцях${r('menus')}.`,

    's7.ctl.h': `Вкладки, сегменти, тумблери`,
    's7.ctl.lead': `Три контроли схожі на вигляд і роблять різне. Сплутати їх — те саме, що дати одному кольору два значення.`,
    'ctl.h.what': `Контрол`,
    'ctl.h.for': `Для чого`,
    'ctl.h.lim': `Обмеження`,
    'ctl.tabs.what': `Вкладки`,
    'ctl.tabs.for': `Окремі ділянки з різним вмістом${r('carbon-tabs')}. Найуживаніша вкладка — перша й типова${r('tabs')}.`,
    'ctl.tabs.lim': `Що менше, то краще. Підпис — одне-два слова. Вибрану позначають щонайменше двома ознаками. Вкладки не складають у кілька рядів і не вживають, коли вміст треба порівнювати${r('tabs', 'carbon-tabs')}.`,
    'ctl.seg.what': `Перемикач вмісту, сегмент`,
    'ctl.seg.for': `Інший погляд на той самий вміст; стоїть рівнем нижче за вкладки${r('carbon-switcher')}. Близькі варіанти, що стосуються об'єкта, стану чи вигляду${r('apple-seg')}.`,
    'ctl.seg.lim': `Не більше приблизно п'яти—семи сегментів на широкому екрані. В одному контролі не змішують дії й вибір${r('apple-seg')}. Його не вживають як «так / ні»: для цього є тумблер${r('carbon-switcher')}.`,
    'ctl.tg.what': `Тумблер`,
    'ctl.tg.for': `Два взаємовиключні стани з негайною дією, без кнопки «Зберегти»${r('toggle')}.`,
    'ctl.tg.lim': `Підпис каже, що буде у стані «увімкнено»${r('toggle')}.`,
    's7.ctl.after': `GOV.UK радить вкладки, коли перший розділ найпотрібніший і розділи не треба бачити разом. І чесно застерігає: сам компонент у них ще не перевірено дослідженням із користувачами${r('govuk-tabs')}.`,

    's7.tbl.h': `Дії в таблицях`,
    's7.tbl.lead': `У таблиці людина робить чотири речі: шукає записи, порівнює їх, переглядає чи змінює один рядок, виконує дію над кількома. Кнопки просто в рядку годяться для однієї-двох дій. Більше — тісно; або їх ховають за наведення чи «три крапки», а це гірше для помітності й доступності. Великий запис краще редагувати в немодальній бічній панелі: таблицю при цьому видно. Масові дії — прапорець у рядку, кнопки над або під таблицею${r('tables')}. Carbon описує те саме як компонент: після вибору рядків угорі з'являється панель масових дій, а дії рядка живуть у меню переповнення; якщо їх менше трьох — іконками в рядку${r('carbon-table')}.`,

    /* ── 08 ── */
    's8.h': `Розбір планувальника: кнопки й панелі`,
    's8.p': `Що добре, що ні, і варіанти — без вердикту`,
    's8.lead': `Тими самими очима ми пройшли шапку, панелі восьми вкладок і двадцять діалогів. Формат той самий, що в розділі 5: ось що знайшли. Усі розміри нижче — зі стилів, без вимірювання в браузері; де оцінка залежить від сусідів на екрані, ми так і пишемо.`,
    's8.good.h': `Що вже добре`,
    'good.dialogs.n': `20`,
    'good.dialogs.ns': `діалогів`,
    'good.dialogs.t': `Один порядок кнопок`,
    'good.dialogs.b': `У всіх двадцяти діалогах «Скасувати» стоїть ліворуч, головна кнопка — крайня права, підвал вирівняно праворуч, третя дія — ліворуч через проміжок. Це порядок Apple, Carbon і Atlassian${r('apple-alerts', 'carbon-modal', 'atl-modal')}. Він протилежний класичному Windows${r('win-dialog')} — і це нормально, якщо порядок один на весь продукт${r('okcancel')}. Кнопки названо дією: «Створити», «Застосувати», а не «ОК».`,
    'good.icons.n': `95`,
    'good.icons.ns': `кнопок-іконок`,
    'good.icons.t': `Кожна має ім'я й підказку`,
    'good.icons.b': `Усі кнопки-іконки мають доступне ім'я й текст підказки. У діалозі підтвердження фокус стоїть на «Скасувати», а небезпечна дія не залита кольором — як радять Nielsen і Apple${r('okcancel', 'apple-buttons')}.`,
    'good.undo.n': `26–36 px`,
    'good.undo.ns': `основні цілі`,
    'good.undo.t': `Миша проходить, скасування є`,
    'good.undo.b': `Кнопки, іконки, вкладки, пункти меню й рядки таблиць мають 26–36 px і проходять мінімум 24 px просто за розміром${r('wcag258')}. Скасування є майже всюди, а підтвердження з'являється там, де наслідок неочевидний${r('confirm', 'win-confirm')}. Задачу редагують у немодальній бічній панелі: таблицю при цьому видно${r('tables')}.`,

    's8.map.h': `Панель «Плану» сьогодні`,
    's8.map.lead': `Найповніша панель продукту — на вкладці «План». На широкому екрані в ній 27–29 контролів у восьми групах із шістьма роздільниками. На схемі панель розгорнуто згори донизу: <b>смуга — це група</b>, у тому порядку, як групи стоять на екрані зліва направо; число в назві — скільки в групі контролів. Останні три картки нижньої смуги — не кнопки, а вміст меню «Ще». Дріт показує, що куди ховається, коли панель не влазить у вікно. Натисніть на картку — побачите, що це за контрол і що ми про нього записали.`,
    's8.map.note': `<b>Про «часте» й «рідкісне».</b> Ці два сценарії — припущення, а не замір: даних про частоту вжитку в нас немає. Поділ узято з варіанта П1 нижче. Перш ніж щось пересувати, потрібне спостереження: що людина справді тисне на цій панелі щодня. Сценарії «Вигляд» і «Небезпечне» — зі звірки коду, без припущень.`,

    's8.bad.h': `Що не так: дванадцять знахідок`,
    'find.h.what': `Що знайшли`,
    'find.h.why': `Чому це проблема`,
    'find.f1.what': `Панель «Плану»: 27–29 контролів у восьми групах.`,
    'find.f1.why': `Це більше за будь-який з орієнтирів: три групи в Apple${r('apple-toolbars')}, п'ять дій у Carbon${r('carbon-table')}. Що саме ховається в «Ще» першим, задано наперед, а коли — вирішує ширина вікна, не частота вжитку${r('win-toolbars')}.`,
    'find.f2.what': `«Ще» й «Експорт» є лише на «Плані». А в «Ще» лежить загальне: налаштування, мова, клавіші, підказки, «про продукт», календар.`,
    'find.f2.why': `З інших вкладок до цього можна дістатися тільки через палітру команд. Швидкий шлях не може бути єдиним${r('accel')}, а загальні дії не змішують в одному меню з діями над конкретним${r('ctxmenu')}.`,
    'find.f3.what': `«Скасувати» й «повторити» на п'яти вкладках стоять у трьох різних місцях. Ще на трьох вкладках їх немає — хоча на «Бюджеті» є що правити.`,
    'find.f3.why': `Команду, що повторюється на різних сторінках, тримають у тому самому місці${r('win-cmdbar')}.`,
    'find.f4.what': `«Видалити» стоїть за 8 px від «Закрити» в шапці трьох карток: стейкхолдера, вимоги, запису змін. У рядку «Людей» — за 2 px від «показати завантаження».`,
    'find.f4.why': `Руйнівну команду відділяють від частих${r('win-confirm', 'win-toolbars')}. Стейкхолдера й вимогу видаляють без підтвердження: рятує лише Ctrl+Z.`,
    'find.f5.what': `Три кнопки мають видимий підпис «Готово», а доступне ім'я — «Закрити» чи «Закрити перевірку».`,
    'find.f5.why': `Це пряме порушення вимоги 2.5.3 рівня A: ім'я має містити видимий текст, інакше голосове керування не спрацьовує${r('wcag253')}.`,
    'find.f6.what': `Підказка з'являється лише за вказівником миші; за фокусом із клавіатури її немає. І всі підказки вимикаються одним перемикачем.`,
    'find.f6.why': `Підказку показують і за наведенням, і за фокусом${r('tooltips')}. Без підказок дев'ять кнопок панелі «Плану» лишаються без жодної видимої назви, а загальновідомі серед них хіба «скасувати» й «повторити»${r('icons')}.`,
    'find.f7.what': `Чипи обмежень у шапці — 16 px заввишки, а над ними впритул стоять інші кнопки. Окремих розмірів для дотику немає взагалі.`,
    'find.f7.why': `За стилями чипи, ймовірно, не проходять мінімум 24 px навіть за винятком «відстань»${r('wcag258')}; у браузері ми цього ще не міряли. На планшеті ті самі 22–28 px стоять проти 44–48${r('apple-buttons', 'android')}.`,
    'find.f8.what': `На «Плані» три сегменти поспіль — масштаб, вигляд, рядки — виглядають однаково. На WBS «рівні 1 / 2 / 3 / усі» — це кнопки-дії без вибраного стану, оформлені як сегмент.`,
    'find.f8.why': `Масштаб — параметр, вигляд і рядки — режими, «рівні» — дії. А сегмент — це вибір, і дії з вибором у ньому не змішують${r('apple-seg')}.`,
    'find.f9.what': `Одна іконка — дві команди. «Вписати проєкт» і «оптимізувати»; «до сьогодні» й «перейти до задачі»; хрестик — і «закрити панель», і «прибрати зв'язок».`,
    'find.f9.why': `Однакову функцію позначають однаково — отже, різну по-різному${r('wcag324')}. А хрестик і без того двозначний${r('cancel-close')}.`,
    'find.f10.what': `Правило «коли питати» ніде не записане. Видалення ризику питає завжди, видалення вимоги — ніколи.`,
    'find.f10.why': `Підтвердження має сенс там, де наслідок тяжкий або його не скасувати${r('confirm')}. І саме скасування не рятує, якщо людина не помітила, що щось зникло${r('win-confirm')}.`,
    'find.f11.what': `Головна дія «Додати» на «Плані» — залита кнопка, а на «Людях», «Ризиках» і в реєстрах — звичайна. «Готово» в діалогах буває то головною, то звичайною.`,
    'find.f11.why': `Та сама функція — той самий вигляд${r('wcag324')}.`,
    'find.f12.what': `У рядку «Людей» — три іконки: турбота, завантаження, видалити. У таблиці плану, навпаки, жодної видимої дії в рядку: кнопки структури — на панелі вгорі, видалення — лише клавішею.`,
    'find.f12.why': `Кнопки в рядку годяться для однієї-двох дій${r('tables')}; від трьох Carbon радить меню рядка${r('carbon-table')}. А пов'язане ставлять поруч із тим, чого воно стосується${r('fitts')}.`,

    's8.sizes.h': `Розмір цілей: що проходить`,
    's8.sizes.lead': `Оцінка за числами зі стилів, без вимірювання в браузері. Мірило — вимога WCAG 2.5.8: 24 px або виняток «відстань»${r('wcag258')}.`,
    'sz.h.place': `Ціль`,
    'sz.h.size': `Розмір за стилями`,
    'sz.v.ok': `проходить`,
    'sz.v.dist': `за відстанню`,
    'sz.v.edge': `на межі`,
    'sz.v.bad': `імовірно ні`,
    'sz.z1.t': `Кнопки, іконки, вкладки, пункти меню, рядки таблиць`,
    'sz.z1.b': `26–36 px.`,
    'sz.z2.t': `Сегменти, лічильники, тумблер, кнопки версії й етапу`,
    'sz.z2.b': `18–22 px заввишки, широкі. Над і під ними інших цілей немає.`,
    'sz.z3.t': `Найменші іконки й зразки кольору`,
    'sz.z3.b': `22×22 px. Проходять, якщо сусід не ближче 1 px; зразки стоять із проміжком 6 px.`,
    'sz.z4.t': `Очистити пошук`,
    'sz.z4.b': `20×20 px усередині поля заввишки 28 px; довкола — клікабельне поле.`,
    'sz.z5.t': `Чипи обмежень у шапці`,
    'sz.z5.b': `16 px. Коло 24 px виходить на 4 px угору — у сусідню кнопку.`,
    's8.sizes.after': `Сітка 26–28 px відповідає звичайному розміру контролів на macOS${r('apple-a11y')}. До 44 px${r('wcag255')} не дотягує ніщо — це свідомий вибір щільного інструмента для миші.`,

    's8.undo.h': `«Скасувати» й «повторити»: де вони стоять`,
    'un.h.tab': `Вкладка`,
    'un.h.where': `Місце на панелі`,
    'un.plan.tab': `«План»`,
    'un.plan.where': `третя група — після шести-семи кнопок`,
    'un.wbs.tab': `WBS`,
    'un.wbs.where': `перша група`,
    'un.add.tab': `«Люди», «Ризики», реєстри`,
    'un.add.where': `друга група — після «Додати»`,
    'un.none.tab': `«Бюджет», EVM, «Аналіз»`,
    'un.none.where': `немає`,

    's8.var.h': `Варіанти складу: шапка й панель «Плану»`,
    's8.var.lead': `Дрібні знахідки лагодяться дрібними правками. Склад шапки й панелі — інша річ: тут є кілька шляхів, і в кожного своя ціна. Показуємо їх так само, як відкриті питання в розділі 5: з плюсами й мінусами, без вердикту.`,
    'v.hd.name': `Шапка`,
    'v.hd.t': `Шапка: близько 26 елементів у двох рядках`,
    'v.hd.b': `Зараз у шапці близько двадцяти інтерактивних елементів і шість текстових. Ліворуч — назад, назва, версія, етап; під ними другий рядок: дати, тривалість, вартість, стан, три чипи обмежень, порада. Посередині — вісім вкладок. Праворуч — дата статусу, валюта й файл, друге вікно, «Зберегти», команди.`,
    'v.hd.1.t': `Мінімальний. У другому рядку лишаються три позначки: стан, найгірше обмеження, порада. Дати, тривалість, вартість, дата статусу, валюта й файл ідуть у віконце за кліком на стан. Праворуч — друге вікно, «Ще», «Зберегти» в самому куті. Кнопка «Команди» з шапки зникає: лишається «Ctrl+K» у рядку стану й пункт у «Ще».`,
    'v.hd.1.plus': `Найменша зміна: з 26 елементів стає близько 18. Головна дія — в куті, а це найлегша ціль${r('fitts')}. «Ще» стає досяжним з усіх вкладок.`,
    'v.hd.1.minus': `Дати й вартість — на клік далі: хто звик бачити їх постійно, втратить. Звичне місце «Команд» зміниться, а перестановки ламають звичку${r('figma')}.`,
    'v.hd.2.t': `Три зони. Ліворуч — «хто»: назад, назва, версія, етап, стан. У центрі — «де»: вісім вкладок. Праворуч — «що зробити»: друге вікно, «Ще», «Зберегти». Обмеження, порада й довідка про файл переходять у рядок стану внизу.`,
    'v.hd.2.plus': `Один рядок замість двох, кожна зона відповідає на одне питання${r('region')}. Чипи обмежень стають повнорозмірними цілями.`,
    'v.hd.2.minus': `Обмеження — головна новина етапу «контракт» — ідуть униз екрана, де їх легше проґавити${r('proximity')}. Рядок стану на «Плані» перевантажується.`,
    'v.hd.3.t': `Вкладки ліворуч. Вісім вкладок стають вертикальною смугою зліва, з іконкою й підписом. У шапці лишаються назва, версія, етап, стан, обмеження, а праворуч — друге вікно, «Ще», «Зберегти».`,
    'v.hd.3.plus': `Відповідає звичці: головна навігація застосунку зазвичай ліворуч${r('menus')}. Шапка звільняється; вкладок може ставати більше без тисняви.`,
    'v.hd.3.minus': `Мінус 56–72 px ширини діаграми — найціннішого місця. Найбільша переробка: потрібні вісім нових іконок, а іконка без підпису рідко зрозуміла${r('icons')}.`,
    'v.tb.name': `Панель «Плану»`,
    'v.tb.t': `Панель «Плану»: 27–29 контролів у восьми групах`,
    'v.tb.b': `Зараз у ряду стоять усі вісім груп зі схеми вище: додати, структура й панелі, історія, масштаб, вигляд, шари плану, пошук, меню.`,
    'v.tb.1.t': `«Вигляд» як меню. У ряду лишаються: «Додати задачу», скасувати й повторити, три кнопки структури, сегмент вигляду, масштаб кнопкою-меню, нове меню «Вигляд», пошук, фільтр, «Оптимізувати», «Експорт» — 15–17 контролів у п'яти групах. У «Вигляд» ідуть рядки, критичний шлях, базовий план, легенда, смуга ризиків, План Б, обидві панелі, «вписати», «сьогодні». У «Ще» лишається рідкісне планове.`,
    'v.tb.1.plus': `Поділ за змістом — «дії» і «як показувати» — і за частотою${r('win-toolbars')}. Зникають три сегменти поспіль${r('apple-seg')}.`,
    'v.tb.1.minus': `Критичний шлях і «рядки: люди» — на клік далі. Якщо їх перемикають щохвилини, це втрата; даних про це немає. Меню на 10–11 пунктів потребує підписаних розділів${r('dix')}.`,
    'v.tb.2.t': `Дві зони без меню. Ліворуч дії: «Додати», скасувати й повторити, структура, «Оптимізувати». Праворуч — спільна область із тлом і підписом «Вигляд»: вигляд, рядки, масштаб, критичний шлях, базовий план, «вписати», «сьогодні», дві панелі. Далі пошук, фільтр, «Експорт».`,
    'v.tb.2.plus': `Нічого не ховається, звичні кнопки на місці${r('win-toolbars')}. Дві зони читаються одразу${r('region')}. Найдешевше.`,
    'v.tb.2.minus': `Кількість не зменшується — близько 26. На екрані 1280 px ховання все одно спрацює. Три сегменти лишаються поруч.`,
    'v.tb.3.t': `Панель вибраного. Без вибору — короткий ряд, як у П1. Коли вибрано рядки, ліву частину заступає панель вибраного: «Вибрано 3», рівень вище, нижче, зв'язати, панель задачі, додати ризик, видалити, закрити.`,
    'v.tb.3.plus': `Дії над рядками з'являються тоді, коли мають сенс, і з підписами${r('tables', 'carbon-table')}. «Видалити» отримує видиме місце, відділене від частих дій.`,
    'v.tb.3.minus': `Панель «стрибає» під рукою. Це проти поради вимикати, а не прибирати${r('win-toolbars')}, і проти досвіду Figma, де нестабільний інтерфейс відкотили${r('figma')}. Джерела тут розходяться: Carbon — за, Windows — проти.`,
    's8.note': `<b>Чому без вердикту.</b> Варіанти панелі спираються на поділ «часте / рідкісне», а даних про частоту в нас немає. Спершу спостереження, потім макет, потім рішення. Що вибрали й що з цього вийшло — напишемо окремо.`,

    /* ── 09 ── */
    's9.h': 'Як це роблять інші',
    's9.p': 'Project проти Jira, оновлення Figma, стрічка Microsoft',
    's9.lead': 'Три приклади з дорослих продуктів. Перший — про колір смуги на діаграмі. Два інші — про те, як стримувати ріст інтерфейсу.',
    'oth.bars.k': 'Колір смуги',
    'oth.bars.t': 'Project проти Jira',
    'oth.bars.b': `У Microsoft Project увімкнений показ критичного шляху робить смуги критичних задач червоними; в інших виглядах критичний шлях підсвічується жовтим${r('msproject')}. У Jira смуги на часовій шкалі фарбують або за категорією статусу (сірий, синій, зелений), або власним кольором чи кольором епіка; типовий колір — фіолетовий, і колір батьківського елемента переходить на дочірні${r('jira')}.`,
    'oth.bars.l': 'Підходи протилежні: у Project колір смуги — стан розрахунку, у Jira — вибір користувача або категорія статусу. Спільне одне: в одному вигляді колір смуги має одне значення.',
    'oth.figma.k': 'Ріст функцій',
    'oth.figma.t': 'Оновлення Figma 2024 року',
    'oth.figma.b': `Вихідна проблема, за словами команди: оновлення накопичуються, і те, що було простим, стає без потреби складним. Мета — спростити Figma, не спрощуючи того, що нею можна зробити. Панель властивостей перевпорядкували за важливістю, споріднені параметри об'єднали, інтерфейс дали сховати. Після тестів частину відкотили: інтерфейс, що з'являється лише під курсором; бічні панелі, що відкриваються самі; перестановку звичних полів — вона ламала м'язову пам'ять${r('figma')}.`,
    'oth.figma.l': 'Це блог компанії про себе, тож беремо його як ілюстрацію, а не як доказ. Ілюстрація корисна: навіть добре спрощення частково відкочують після тестів.',
    'oth.ribbon.k': 'Команди й місця',
    'oth.ribbon.t': 'Стрічка Microsoft',
    'oth.ribbon.b': `Настанова про стрічку чесна щодо меж: вкладки роблять її модальною. Якщо потрібно понад сім основних вкладок або люди мусять постійно перемикатись заради частих дій — стрічка не підходить. Команди певного типу об'єкта збирають у контекстні вкладки. Між командою й місцем, де вона живе, має бути ясна й єдина відповідність: другий, менш прямий шлях до тієї самої дії шкодить. І нові функції не виносять на головне місце з маркетингових міркувань${r('ribbons')}.`,
    'oth.ribbon.l': 'У нас є саме такий другий шлях: аудит команди відкривається і з «Реєстрів», і кнопкою на «Людях» — а кнопка без попередження переносить на іншу вкладку.',
    'oth.lesson': 'Що з цього для нас.',

    /* ── 10 ── */
    's10.h': 'Чекліст на одну сторінку',
    's10.p': 'Двадцять дві дії, кожну можна перевірити',
    's10.lead': 'Усе вище — у вигляді списку з двох частин: дванадцять пунктів про колір і десять про розташування. Ним можна пройти будь-який інтерфейс, не лише планувальник.',
    'chk.g.color': 'Колір',
    'chk.g.place': 'Розташування',
    'chk.1': `<b>Випишіть усі кольори інтерфейсу</b> й навпроти кожного — що він означає. Два значення в одного кольору — конфлікт${r('apple')}.`,
    'chk.2': '<b>Розкладіть значення на чотири роботи:</b> стан, дія, категорія, величина. Колір, що потрапив у дві, — кандидат на розділення.',
    'chk.3': `<b>Знайдіть усе, що пофарбовано кольором дії, але не натискається.</b> Кожне таке місце — або помилка, або записаний виняток${r('apple')}.`,
    'chk.4': '<b>Порахуйте відстань між сусідніми ролями.</b> Наш орієнтир: менше 20 за ΔE — на тонких лініях і дрібних знаках вони сперечатимуться.',
    'chk.5': '<b>Перевірте кожне оформлення й кожну тему окремо.</b> Конфлікт може жити лише в одному з них — як у нас.',
    'chk.6': `<b>Порахуйте барви на найщільнішому екрані.</b> Орієнтир — дві-три барви, решту різниці дають світлота й насиченість${r('stone')}. Спершу скоротіть кольори, потім додавайте форму${r('healey')}.`,
    'chk.7': `<b>Переведіть екран у відтінки сірого.</b> Усе важливе має читатись і так${r('stone')}.`,
    'chk.8': `<b>Для кожного стану назвіть другий носій, крім кольору:</b> підпис, значок, форму чи товщину лінії${r('wcag141')}.`,
    'chk.9': `<b>Виміряйте контраст.</b> Текст — щонайменше 4.5:1; знаки, межі елементів і фокус — 3:1${r('wcag143', 'wcag1411')}.`,
    'chk.10': `<b>Не лишайте червоний проти зеленого єдиною різницею.</b> Додайте підпис або візьміть іншу пару${r('few', 'pajamas-viz')}.`,
    'chk.11': `<b>На кожному екрані знайдіть головну кнопку.</b> Якщо їх дві — і це не тимчасовий потік на кшталт діалогу, — одна зайва${r('carbon-button')}.`,
    'chk.12': `<b>Випишіть режими екрана й перемножте їх.</b> Кожен активний режим має бути видно двома ознаками й названо словом${r('modes')}.`,

    'chk.13': `<b>Виберіть один порядок кнопок у діалогах</b> і перевірте кожен діалог. Який саме порядок — неважливо; важливо, що він один${r('okcancel')}.`,
    'chk.14': `<b>Назвіть кожну кнопку дією, а не «ОК».</b> «Скасувати» лишіть там, де справді є що скасувати${r('okcancel', 'apple-alerts')}.`,
    'chk.15': `<b>Порахуйте контроли на найповнішій панелі</b> й розкладіть їх за частотою вжитку. Часте й пряме — в ряд, решта — в меню. Ділить частота, а не ширина вікна${r('win-toolbars')}.`,
    'chk.16': `<b>Виміряйте найменші цілі.</b> Для вказівника підлога — 24 px; менша ціль проходить лише з проміжком. Для дотику — 44–48${r('wcag258', 'apple-buttons', 'android')}.`,
    'chk.17': `<b>Не ріжте меню до семи пунктів.</b> Згрупуйте пункти, підпишіть групи й приберіть зайвий рівень${r('miller', 'stm', 'dix')}.`,
    'chk.18': `<b>Знайдіть кожну руйнівну дію</b> й дайте три відповіді: чи відділена вона від частих кнопок, чи можна її повернути, чи помітить людина, що щось зникло${r('win-confirm')}. Питати «точно?» — лише там, де наслідок тяжкий або незворотний${r('confirm')}.`,
    'chk.19': `<b>Вимкніть підказки й подивіться, які кнопки лишилися без назви.</b> А ввімкнені підказки мають з'являтись і за фокусом із клавіатури${r('icons', 'tooltips')}.`,
    'chk.20': `<b>Звірте видимий підпис кожної кнопки з її доступним ім'ям.</b> Ім'я має містити той самий текст${r('wcag253')}.`,
    'chk.21': `<b>Пройдіть усі екрани й випишіть, де стоять «Додати», «Скасувати», пошук і «Ще».</b> Та сама команда — те саме місце; одна іконка — одна команда${r('win-cmdbar', 'wcag324')}.`,
    'chk.22': `<b>Перевірте, що вкладка, сегмент і тумблер роблять різне.</b> Вкладка — інший вміст, сегмент — інший погляд на той самий, тумблер — увімкнено чи вимкнено одразу${r('carbon-switcher', 'toggle')}.`,

    /* ── 11 ── */
    's11.h': 'Джерела',
    's11.p': 'Лише ті, на які є виноски в тексті',
    's11.lead': 'Усі джерела відкрито й прочитано; дата перегляду — 2026-10-11. Номер у списку збігається з номером виноски. Три позиції мають застереження просто в списку: дві роботи ми читали лише в анотації, одну сторінку беремо як ілюстрацію. Настанови Windows про діалоги, панелі й підтвердження написано за доби Windows 7 — Microsoft сама позначає їх як не оновлені. Числа відстаней і контрасту в розділі 5 — власні розрахунки автора; розміри цілей у розділі 8 — зі стилів, без вимірювання в браузері.',
    'src.note.stone': 'Прочитано копію на сторонньому сайті; першоджерело — Perceptual Edge.',
    'src.note.figma': 'Блог компанії про власний продукт — ілюстрація, а не доказ.',
    'src.note.abstract': 'Прочитано лише анотацію.',
    'src.note.illus': 'Ілюстрація, не першоджерело.',
    'src.note.win7': 'Настанова доби Windows 7; Microsoft позначає її як не оновлену.',

    /* ── схема: смуги, колонки, дроти ── */
    'band.act': 'Дія',
    'band.state': 'Стан',
    'band.cat': 'Категорія',
    'band.mag': 'Величина',
    'band.none': 'Ролі немає',
    'band.state.sum.t': 'Стан: чотири ролі',
    'band.state.sum.s': 'crit · err · warn · ok',
    'band.state.sum.b': 'Критичний шлях, помилка, увага й «добре» — у кожної ролі свій токен і свої місця. За змістом сюди ж належать «триває», «не збережено» й стан людини, які взяли чужий колір.',
    'band.cat.sum.t': 'Категорія: людина',
    'band.cat.sum.s': '--c-* · 10 кольорів',
    'band.cat.sum.b': 'Десять кольорів, які лише відрізняють одну людину від іншої. Ті самі кольори пішли на колір задачі й на групи аудиту.',
    'band.mag.sum.t': 'Величина: дані й зони ризику',
    'band.mag.sum.s': '--data-accent · --zone-1…4',
    'band.mag.sum.b': 'Перебіг і дані мають свій токен, зони ризику — шкалу з чотирьох ступенів. За змістом сюди належать віхи найму й смужки перебігу, які взяли колір дії.',
    'band.none.sum.t': 'П\'ять місць без власної ролі',
    'band.none.sum.s': 'К2 · К3 · К6',
    'band.none.sum.b': 'Вибране й наведене на полотні, блок-прикраса, колір задачі на вибір, групи аудиту. Ролі для них немає, тому кожне взяло найближчий помітний колір.',
    'grp.role': 'Роль',
    'grp.token': 'Токен',
    'grp.own': 'Місця за призначенням',
    'grp.lent': 'Місця, що взяли чужий колір →',
    'api.token': 'токен',
    'api.paints': 'малює',
    'api.k1': 'К1', 'api.k2': 'К2', 'api.k3': 'К3', 'api.k4': 'К4', 'api.k5': 'К5', 'api.k6': 'К6', 'api.k7': 'К7',
    'pop.sky': 'блакитне',
    'pop.calm': 'спокійне',
    'pop.both': 'в обох оформленнях',
    'pop.code': 'у коді',
    'pop.conflict': 'конфлікт',

    /* ── схема: вузли ── */
    'node.r-act.t': 'Дія',
    'node.r-act.s': 'сюди можна натиснути',
    'node.r-act.b': 'Колір, який каже: це можна натиснути. У блакитному оформленні він синій, у спокійному — помаранчевий. Роль одна, і більше нічого цей колір означати не має.',
    'node.t-signal.t': '--signal',
    'node.t-signal.s': 'дія · фокус · вибране',
    'node.t-signal.b': 'Токен дії з відтінками для посилань, вибраного й наведення. За призначенням малює три групи місць. Ще сім місць узяли його, хоча це не дія: конфлікти К1–К5.',
    'node.p-btn.t': 'Головна кнопка',
    'node.p-btn.s': 'усі екрани',
    'node.p-btn.b': 'Головна дія екрана: «Зберегти», «Додати задачу». Саме для неї цей колір і заведено.',
    'node.p-focus.t': 'Фокус поля й прапорець',
    'node.p-focus.s': 'форми',
    'node.p-focus.b': 'Рамка поля, у яке зараз вводять, і позначений прапорець. Це відгук на дію — колір ужито за призначенням.',
    'node.p-sel.t': 'Вибране в таблиці',
    'node.p-sel.s': '--signal-soft',
    'node.p-sel.b': 'Вибраний рядок і наведення — блідим відтінком кольору дії. У таблиці це працює: поруч немає даних того самого кольору.',
    'node.r-crit.t': 'Критичний шлях',
    'node.r-crit.s': 'стан розрахунку',
    'node.r-crit.b': 'Задачі, затримка яких зсуває кінець проєкту. Це не помилка, а результат розрахунку, тому роль окрема від «помилки».',
    'node.r-err.t': 'Помилка',
    'node.r-err.s': 'прострочено · понад ліміт',
    'node.r-err.b': 'Щось пішло не так: прострочено, перевищено бюджет чи завантаження.',
    'node.r-warn.t': 'Увага',
    'node.r-warn.s': 'варто глянути',
    'node.r-warn.b': 'Ще не помилка, але варто подивитись. В асистенті цим кольором позначено ще й демо-режим, хоча демо — не попередження (К8).',
    'node.r-ok.t': 'Добре',
    'node.r-ok.s': 'норма · готово',
    'node.r-ok.b': 'Усе гаразд: готово, у межах, краще за план.',
    'node.t-crit.t': '--crit',
    'node.t-crit.s': 'окремо від помилки',
    'node.t-crit.b': 'Власний токен критичного шляху. У блакитному — яскраво-червоний, у спокійному — цегляний. Контраст до білого за нашим розрахунком: 3.63 і 5.64.',
    'node.t-err.t': '--err-*',
    'node.t-err.s': 'заливка · тло · текст',
    'node.t-err.b': 'Трійка кольорів помилки. Те саме значення мають ще три токени: перевищення на графіку, перевантаження й четверта зона ризику.',
    'node.t-warn.t': '--warn-*',
    'node.t-warn.s': 'заливка · тло · текст',
    'node.t-warn.b': 'Трійка кольорів уваги. Заливка як самостійний знак на білому слабка: контраст 2.31 і 2.19 за нашим розрахунком, а треба 3:1.',
    'node.t-ok.t': '--ok-*',
    'node.t-ok.s': 'заливка · тло · текст',
    'node.t-ok.b': 'Трійка кольорів «добре». Однакова в обох оформленнях. Те саме значення має перша зона ризику.',
    'node.p-critbar.t': 'Критична смуга',
    'node.p-critbar.s': 'діаграма · таблиця',
    'node.p-critbar.b': 'Колір тут не єдиний носій: є товща лінія, скоба над етапом, контур віхи, значок у таблиці й квадратна крапка в позначці. Це зразок, як треба.',
    'node.p-late.t': 'Прострочена смуга',
    'node.p-late.s': 'діаграма',
    'node.p-late.b': 'Червона рамка на смузі. На діаграмі це лише колір; у таблиці є мітка й дата.',
    'node.p-sprint.t': 'Лінія картки спринту',
    'node.p-sprint.s': 'спринти',
    'node.p-sprint.b': 'Бурштинова лінія — задачі «переливаються» в наступний спринт, червона — спринт перевантажено. На самій картці, крім кольору, нічого немає.',
    'node.p-done.t': 'Позначка «готово»',
    'node.p-done.s': 'таблиці · лічильники',
    'node.p-done.b': 'Зелена позначка «готово» й зелений відсоток виконання.',
    'node.p-run.t': 'Позначка «триває»',
    'node.p-run.s': 'К5 · шапка · асистент',
    'node.p-run.b': 'Конфлікт К5. «Активний» у шапці й «в роботі» в асистенті показано кольором дії. У блакитному це синій, як заведено в системах дизайну. У спокійному «триває» стає помаранчевим — сусідом «уваги».',
    'node.p-health.t': 'Стан людини',
    'node.p-health.s': 'К7 · люди · аудит',
    'node.p-health.b': 'Конфлікт К7, терпимий. Стан людини й теплокарта аудиту показано шкалою зон ризику. Зміст близький: «від доброго до поганого». Але «жовтий» стан у застосунку жовтий, а в асистенті бурштиновий.',
    'node.p-dirty.t': 'Крапка «не збережено»',
    'node.p-dirty.s': 'К4 · шапка',
    'node.p-dirty.b': 'Конфлікт К4. Крапка біля назви проєкту показує, що є незбережені зміни. Це стан, а не дія, але колір — дії.',
    'node.r-person.t': 'Людина',
    'node.r-person.s': 'ідентичність',
    'node.r-person.b': 'Колір відрізняє одну людину від іншої й нічого не каже про її стан. Наше правило: кольори людей — ідентичність, ніколи не стан.',
    'node.t-c.t': '--c-*',
    'node.t-c.s': '10 кольорів',
    'node.t-c.b': 'Десять кольорів, спільних для обох оформлень. У спокійному «clay» стоїть близько до кольору дії (відстань 16), а «slate» — до типової смуги задачі (7).',
    'node.p-person.t': 'Смуга й аватар людини',
    'node.p-person.s': 'діаграма · люди',
    'node.p-person.b': 'Смуга задачі бере колір виконавця; той самий колір — у списку людей. Ужито за призначенням.',
    'node.r-data.t': 'Дані й перебіг',
    'node.r-data.s': 'не дія',
    'node.r-data.b': 'Смужки перебігу, позначки на графіках: показують, скільки зроблено. На них не тиснуть.',
    'node.r-zone.t': 'Зона ризику',
    'node.r-zone.s': 'шкала 1–4',
    'node.r-zone.b': 'Чотири ступені від найменшого ризику до найбільшого. Це впорядкована шкала, тобто величина.',
    'node.t-data.t': '--data-accent',
    'node.t-data.s': 'дані, не дія',
    'node.t-data.b': 'Окремий токен для даних і перебігу. У блакитному він дорівнює кольору дії, у спокійному — приглушений синій. Заведений саме для того, щоб дані не брали колір дії.',
    'node.t-zone.t': '--zone-1…4',
    'node.t-zone.s': 'чотири ступені',
    'node.t-zone.b': 'Зелений, жовтий, бурштиновий, червоний. Три з чотирьох значень — ті самі, що в станів: «добре», «увага», «помилка». Жовта зона як самостійний знак на білому слабка: контраст 1.72 і 1.63.',
    'node.p-progress.t': 'Смужки перебігу',
    'node.p-progress.s': 'аналіз · спринти',
    'node.p-progress.b': 'Заповнення смужок в аналізі, завантаження спринту, радар аудиту. Ужито за призначенням.',
    'node.p-zones.t': 'Зони ризику',
    'node.p-zones.s': 'реєстр · діаграма',
    'node.p-zones.b': 'Крапка зони в дереві ризиків і значок ризику на смузі. Значок має різну форму для загрози, можливості й захисту — це добре. Крапка в дереві, крім кольору, не має нічого.',
    'node.p-hire.t': 'Віхи найму',
    'node.p-hire.s': 'К1 · часова шкала',
    'node.p-hire.b': 'Конфлікт К1. Ромби на шкалі — це дані, але намальовано їх кольором дії. У спокійному це помаранчеві знаки поруч із червоними критичними лініями.',
    'node.p-step.t': 'Перебіг показу й кроків',
    'node.p-step.s': 'К4 · трейлер · кроки',
    'node.p-step.b': 'Конфлікт К4. Смужка перегляду трейлера, номер кроку, крапка показу «як заповнити». Це перебіг, а не дія.',
    'node.p-taskcolor.t': 'Колір задачі на вибір',
    'node.p-taskcolor.s': 'К6 · панель задачі',
    'node.p-taskcolor.b': 'Конфлікт К6. Користувач сам фарбує задачу кольором із палітри людей. Тепер той самий колір на смузі може означати і виконавця, і чийсь вибір.',
    'node.p-audit.t': 'Групи в аудиті команди',
    'node.p-audit.s': 'К6 · аудит',
    'node.p-audit.b': 'Конфлікт К6. Групи в аудиті пофарбовано кольорами людей, а один із них стоїть четвертою категорією поруч із зонами. Правило «ніколи не стан» тут порушене.',
    'node.p-cansel.t': 'Вибране на полотні',
    'node.p-cansel.s': 'К2 · діаграма',
    'node.p-cansel.b': 'Конфлікт К2. Рамка активної смуги й підсвітка задач ризику — кольором дії. На полотні той самий колір малює і взаємодію, і дані.',
    'node.p-arrow.t': 'Наведена стрілка',
    'node.p-arrow.s': 'К2 · діаграма',
    'node.p-arrow.b': 'Конфлікт К2. За кодом, наведена стрілка зв\'язку стає помаранчевою замість критично-червоної: два сусідні відтінки на лінії 1.75 px.',
    'node.p-about.t': 'Блок на «Про продукт»',
    'node.p-about.s': 'К3 · сторінка',
    'node.p-about.b': 'Конфлікт К3. Тло змістового блоку без жодної кнопки. Найбільша пляма кольору дії в продукті — проти правила «лише дія, не декор».',

    /* ── друга схема: панель «Плану» сьогодні ──
       Смуга — група панелі (зліва направо на екрані = згори донизу тут);
       число в назві смуги — скільки в групі контролів. */
    'band.g1': `1 · Додати · 2`,
    'band.g2': `2 · Структура · 5`,
    'band.g3': `3 · Історія · 2`,
    'band.g4': `4 · Масштаб · 6`,
    'band.g5': `5 · Вигляд · 6`,
    'band.g6': `6 · Шари · 2`,
    'band.g7': `7 · Пошук · 2–4`,
    'band.g8': `8 · Меню · 2`,
    'grp.inmore': `У меню «Ще» →`,
    'api.opens': `відкриває`,
    'api.hide1': `ховається 1-м`,
    'api.hide2': `ховається 2-м`,
    'api.hide4': `ховається 4-м`,
    'api.sameicon': `та сама іконка`,
    'pop.size': `розмір`,

    'node.tb-add.t': `Додати задачу ▾`,
    'node.tb-add.s': `головна · розділена`,
    'node.tb-add.b': `Єдина залита кнопка панелі. Розділена: сама кнопка додає задачу, стрілка відкриває вибір — задача, підзадача чи віха. Це два контроли в одному. На «Людях», «Ризиках» і в реєстрах «Додати» — звичайна кнопка, не залита.`,
    'node.tb-out.t': `Рівень вище`,
    'node.tb-out.s': `іконка без підпису`,
    'node.tb-out.b': `Піднімає задачу на рівень у структурі. Іконка без підпису: назву видно лише в підказці. Коли панель звужується, уся трійка структури ховається в «Ще» другою.`,
    'node.tb-in.t': `Рівень нижче`,
    'node.tb-in.s': `іконка без підпису`,
    'node.tb-in.b': `Опускає задачу на рівень у структурі. У самому рядку таблиці дій немає: кнопки структури стоять тут, угорі, далеко від рядка, якого стосуються.`,
    'node.tb-link.t': `Зв'язати`,
    'node.tb-link.s': `іконка без підпису`,
    'node.tb-link.b': `Зв'язує вибрані задачі. Іконка не з тих, які впізнають без підпису.`,
    'node.tb-ptask.t': `Панель задачі`,
    'node.tb-ptask.s': `іконка · без ознаки стану`,
    'node.tb-ptask.b': `Відкриває й ховає бічну панель задачі. Це перемикач, але ознаки «ввімкнено» в кнопки немає — у сусідньої «Панелі завантаження» вона є. Ховається в «Ще» четвертою.`,
    'node.tb-pload.t': `Панель завантаження`,
    'node.tb-pload.s': `іконка · зі станом`,
    'node.tb-pload.b': `Відкриває й ховає панель завантаження людей. Має ознаку стану — на відміну від сусідньої кнопки. Ховається в «Ще» четвертою.`,
    'node.tb-undo.t': `Скасувати`,
    'node.tb-undo.s': `іконка`,
    'node.tb-undo.b': `Тут це третя група — після шести-семи кнопок. На WBS «скасувати» стоїть першим, на «Людях», «Ризиках» і в реєстрах — другим, після «Додати». На «Бюджеті», EVM та «Аналізі» його немає.`,
    'node.tb-redo.t': `Повторити`,
    'node.tb-redo.s': `іконка`,
    'node.tb-redo.b': `Пара до «Скасувати». Разом вони — головний захист на цій вкладці: задачі видаляють клавішею — і без запитання, якщо серед них немає етапу.`,
    'node.tb-scale.t': `Масштаб`,
    'node.tb-scale.s': `сегмент · 4`,
    'node.tb-scale.b': `День, тиждень, місяць, квартал — чотири контроли в одному сегменті. Це параметр показу, а не режим, але виглядає так само, як два сусідні сегменти режимів. Коли панель звужується, сегмент третім кроком стає кнопкою-меню.`,
    'node.tb-fit.t': `Вписати`,
    'node.tb-fit.s': `іконка без підпису`,
    'node.tb-fit.b': `Вписує весь проєкт у ширину діаграми. Ховається в «Ще» першою. Та сама іконка на вузькому екрані означає іншу команду — «Оптимізувати».`,
    'node.tb-today.t': `Сьогодні`,
    'node.tb-today.s': `іконка без підпису`,
    'node.tb-today.b': `Прокручує діаграму до сьогоднішньої дати. Ховається в «Ще» першою. Та сама іконка в реєстрі вимог означає «перейти до задачі».`,
    'node.tb-view.t': `Вигляд`,
    'node.tb-view.s': `сегмент · до 3`,
    'node.tb-view.b': `Гант, Роадмеп, Спринти — до трьох контролів. Це режим: той самий план, інший погляд. Стоїть п'ятою групою, посередині панелі; на WBS і «Людях» перемикач вигляду йде одразу після «скасувати».`,
    'node.tb-rows.t': `Рядки`,
    'node.tb-rows.s': `сегмент · 2`,
    'node.tb-rows.b': `Задачі або люди — що показувати рядками. Теж режим, і теж сегмент: третій поспіль.`,
    'node.tb-opt.t': `Оптимізувати`,
    'node.tb-opt.s': `кнопка з підписом`,
    'node.tb-opt.b': `Одна з небагатьох кнопок панелі з текстом. Не діє одразу: відкриває діалог із парою «Скасувати» → «Застосувати». На вузькому екрані стає іконкою — тією самою, що й «Вписати».`,
    'node.tb-crit.t': `Критичний шлях`,
    'node.tb-crit.s': `тумблер`,
    'node.tb-crit.b': `Вмикає й вимикає показ критичного шляху. Тумблер із підписом: клікабельний увесь підпис, а не лише повзунок.`,
    'node.tb-base.t': `Базовий план`,
    'node.tb-base.s': `кнопка або меню`,
    'node.tb-base.b': `Показ базового плану й вибір, з яким порівнювати: кнопка або меню. Останнім, п'ятим кроком звуження кнопка стає вузькою. Видалення базового плану — в окремому діалозі, завжди з підтвердженням.`,
    'node.tb-search.t': `Пошук`,
    'node.tb-search.s': `поле · + очистити`,
    'node.tb-search.b': `Поле пошуку з кнопкою «очистити» — це ще один контрол. За стилями вона 20×20 px, тобто на межі мінімуму 24 px: довкола неї клікабельне поле. Пошук є лише на «Плані».`,
    'node.tb-filter.t': `Фільтр`,
    'node.tb-filter.s': `меню · + скинути`,
    'node.tb-filter.b': `Меню фільтра з окремою кнопкою «скинути» — це ще один контрол. Фільтр є на «Плані» й WBS; у реєстрі вимог — свій.`,
    'node.tb-export.t': `Експорт`,
    'node.tb-export.s': `меню · лише тут`,
    'node.tb-export.b': `Меню експорту. Є лише на панелі «Плану».`,
    'node.tb-more.t': `Ще`,
    'node.tb-more.s': `меню · лише тут`,
    'node.tb-more.b': `Меню до двадцяти пунктів у п'яти групах, один рівень. Є лише на панелі «Плану» — хоча частина вмісту стосується всього продукту.`,
    'node.m-plan.t': `Планове`,
    'node.m-plan.s': `PERT · план Б · ризики`,
    'node.m-plan.b': `Перша група меню: PERT, План Б, смуга ризиків і «лише високі». План Б і смуга ризиків — це теж про показ, але живуть вони тут, а не поруч з іншими перемикачами вигляду.`,
    'node.m-over.t': `Те, що не влізло`,
    'node.m-over.s': `переповнення`,
    'node.m-over.b': `Сюди панель ховає групи, коли вікно звужується. Порядок заданий наперед: спершу «вписати» й «сьогодні», потім структура; далі масштаб стає кнопкою-меню; потім ховаються дві панелі; насамкінець звужується кнопка базового плану.`,
    'node.m-gen.t': `Загальне`,
    'node.m-gen.s': `налаштування · мова · …`,
    'node.m-gen.b': `Календар, підказки, налаштування, клавіші, «про продукт», демо й три мови. Це не про план, а про весь продукт. З інших вкладок до цього можна дістатися тільки через палітру команд.`,

    'flow.often.name': `Часте · припущення`,
    'flow.often.1': `<b>Припущення, потрібне спостереження.</b> Даних про частоту в нас немає. «Часте» тут — те, що варіант П1 лишає в ряду. Перше: додати задачу й скасувати помилку.`,
    'flow.often.2': `<b>Структура.</b> Рівень вище, рівень нижче, зв'язати. Якщо це справді щоденні дії, то дивно, що без підпису саме вони і що в «Ще» вони ховаються другими.`,
    'flow.often.3': `<b>Як дивитись і як знайти.</b> Вигляд, масштаб, пошук і фільтр.`,
    'flow.often.4': `<b>Кінець ряду.</b> «Оптимізувати» й «Експорт». Разом у «частому» — 15–17 контролів із 27–29. Знову ж: це припущення.`,
    'flow.view.name': `Вигляд`,
    'flow.view.1': `<b>Три сегменти поспіль.</b> Масштаб — параметр, вигляд і рядки — режими. На панелі вони виглядають однаково.`,
    'flow.view.2': `<b>Ще чотири перемикачі показу, три типи.</b> Критичний шлях — тумблер; базовий план — кнопка або меню; дві панелі — іконки, і лише одна з них показує, що ввімкнена.`,
    'flow.view.3': `<b>Навігація діаграмою.</b> «Вписати» й «сьогодні» — іконки без підпису, що ховаються першими. Іконка «вписати» на вузькому екрані означає ще й «оптимізувати».`,
    'flow.view.4': `<b>І ще частина — в меню.</b> План Б і смуга ризиків теж міняють показ, але лежать у «Ще». Разом усе про вигляд розкидано по п'яти групах.`,
    'flow.rare.name': `Рідкісне · припущення`,
    'flow.rare.1': `<b>Припущення, потрібне спостереження.</b> Що з цього справді рідкісне — ми не міряли. Варіант П1 переносить у меню «Вигляд» рядки, критичний шлях і базовий план.`,
    'flow.rare.2': `<b>Те, що панель ховає вже зараз.</b> «Вписати» й «сьогодні» зникають першими, дві панелі — четвертими. Тобто частину відповіді на «що рідкісне» вже зашито в порядок ховання.`,
    'flow.rare.3': `<b>У меню «Ще».</b> Планове — PERT, План Б, смуга ризиків — і загальне: налаштування, мова, клавіші. Загальне рідкісне, але воно взагалі не про план.`,
    'flow.danger.name': `Небезпечне`,
    'flow.danger.1': `<b>Руйнівної кнопки на панелі немає.</b> Задачі видаляють клавішею Delete. Програма питає, лише якщо серед вибраного є етап; інакше видаляє одразу — і рятує «Скасувати».`,
    'flow.danger.2': `<b>«Оптимізувати» не діє одразу.</b> Кнопка відкриває діалог із парою «Скасувати» → «Застосувати».`,
    'flow.danger.3': `<b>Базовий план.</b> Видалити його можна лише в окремому діалозі, і там програма питає завжди. Небезпечне сусідство ми знайшли не тут, а в картках інших вкладок — про це в таблиці нижче.`,

    /* ── сценарії ── */
    'flow.idle': 'Виберіть сценарій — схема підсвітить один шлях, решта притухне. Або натисніть на будь-яку картку.',
    'flow.act.name': 'Дія',
    'flow.act.1': '<b>Одна роль — один токен.</b> «Сюди можна натиснути» в коді називається <b>--signal</b>. У блакитному оформленні він синій, у спокійному — помаранчевий.',
    'flow.act.2': '<b>Три місця за призначенням.</b> Головна кнопка, фокус поля з прапорцем і вибране в таблиці. На цьому робота кольору дії мала б закінчитись.',
    'flow.crit.name': 'Критичний шлях',
    'flow.crit.1': '<b>Окрема роль.</b> Критичний шлях — не помилка, а результат розрахунку. Тому в нього власний токен <b>--crit</b>.',
    'flow.crit.2': '<b>Не лише колір.</b> Критичну смугу видно ще й за товщою лінією, скобою над етапом, контуром віхи та значком у таблиці.',
    'flow.crit.3': '<b>Сусіди на полотні.</b> Віхи найму й наведена стрілка беруть колір дії. У спокійному оформленні між ним і критичним шляхом відстань 15 — на тонких лініях їх легко сплутати.',
    'flow.state.name': 'Стан',
    'flow.state.1': '<b>Три стани — три трійки.</b> Помилка, увага й «добре» мають по три кольори: заливку, тло й текст.',
    'flow.state.2': '<b>Місця за призначенням.</b> Прострочена смуга, лінія картки спринту, позначка «готово». На картці спринту колір — єдиний носій.',
    'flow.state.3': '<b>Стани, що взяли колір дії.</b> «Триває» й «не збережено» — це стани, але намальовано їх кольором кнопки.',
    'flow.state.4': '<b>Стан чужою шкалою.</b> Стан людини показано зонами ризику. Зміст близький, тож терпимо, — але це ще одне значення в тієї самої шкали.',
    'flow.person.name': 'Людина',
    'flow.person.1': '<b>Категорія, не стан.</b> Десять кольорів лише відрізняють одну людину від іншої.',
    'flow.person.2': '<b>За призначенням.</b> Смуга задачі бере колір виконавця; той самий колір — у списку людей.',
    'flow.person.3': '<b>Ще два значення.</b> Тими самими кольорами користувач фарбує задачу на свій смак, а аудит команди позначає групи.',
    'flow.conf.name': 'Конфлікти',
    'flow.conf.1': '<b>К1 · дані кольором дії.</b> Віхи найму на часовій шкалі.',
    'flow.conf.2': '<b>К2 · вибране й наведене на полотні.</b> Рамка активної смуги й наведена стрілка — поруч із критичним шляхом.',
    'flow.conf.3': '<b>К3 · прикраса.</b> Блок на «Про продукт» без жодної кнопки — найбільша пляма кольору дії.',
    'flow.conf.4': '<b>К4 · перебіг і стан.</b> Смужка перегляду, номер кроку, крапка «не збережено».',
    'flow.conf.5': '<b>К5 · «триває».</b> У спокійному оформленні стає помаранчевим — кольором дії й сусідом «уваги».',
    'flow.conf.6': '<b>К6 · кольори людей.</b> Людина, колір задачі на вибір і групи аудиту — три значення однієї палітри.',
    'flow.conf.7': '<b>К7 · шкала зон.</b> Передає ще й стан людини. Найм\'якший із конфліктів.',
  } };
})();
